(function(global){
'use strict';
const RA=global.RA=global.RA||{};
const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='th'?'Orthographic history: https://en.wikipedia.org/wiki/Thorn_(letter)':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('tenure','Tenure came through Old French teneure, from tenir, “to hold,” ultimately from Latin tenere; it names a period in office and, in universities, a protected permanent appointment.',[C('tenure.s1','任职','During her tenure as director, the museum opened two new galleries.','她担任馆长期间，博物馆新开了两个展厅。','during one’s tenure; a four-year tenure','名词，指担任某个职务的一段时期。','the sentence measures time in the director’s position.','任职'),C('tenure.s2','职位保障','After years of research and teaching, he was granted tenure at the university.','经过多年研究和教学，他获得了这所大学的终身教职。','academic tenure; be granted tenure','名词，指大学授予教师的长期职位保障。','the appointment gives continued academic employment.','职位保障')],M('She served a five-year tenure as director before leaving the post.','She served a five-year term as director before leaving the post.','tenure通常指任职期间；在此指一段任期时可用term，原句该搭配不够自然。','collocation'),[Q(1,'Her tenure as director means…','the period she held that office','the legal deed to the building','a subject’s technical vocabulary','Sense 1 is a period in a position.','meaning'),Q(2,'Academic tenure usually provides…','long-term protection for a university appointment','a one-week trial with no job security','a place where buses end','Sense 2 concerns continuing academic employment.','context'),Q(1,'Which phrase is natural?','during her tenure as director','during her tenure to directorship','tenure of directorly','During introduces the period in office.','grammar'),Q(1,'The old French source tenir meant…','to hold','to frighten','to weave cloth','The historical root is associated with holding or keeping.','word-formation')]);
P('tepee','Tepee (also spelled tipi or teepee) is borrowed from a Lakota word thípi, “dwelling”; the word names a portable conical home traditionally used by some Plains peoples.',C('tepee.s1','居所','The family raised the canvas tepee near the river before the evening rain.','下雨前，一家人在河边搭起了帆布圆锥帐篷。','raise/erect a tepee; live in a tepee','名词，指由杆架支撑、外覆兽皮或帆布的传统圆锥形便携居所。','the poles and canvas form a portable dwelling.','居所'),M('The family slept in a tepee, a permanent stone apartment block with no poles or covering.','The family slept in a tepee, a portable conical dwelling made with poles and a covering.','tepee指可搭建的圆锥形居所，不是固定的石砌公寓。','meaning'),[Q(1,'A tepee is traditionally…','a portable conical dwelling','a railway station at the end of a line','a legal witness statement','That is the source sense of the noun.','meaning'),Q(1,'What supports the tepee in the example?','A frame of poles beneath canvas','A keyboard connected to a computer','A series of terraces on a hill','The context describes a canvas-covered dwelling.','context'),Q(1,'Which phrase is natural?','raise a tepee near the river','raise a tepee to the riverly','tepee a river at raise','Raise is commonly used for putting up a tent-like dwelling.','collocation'),Q(1,'Lakota thípi meant…','dwelling','a frightening event','a third-level course','The borrowed word referred to a place to live.','word-formation')]);
P('tepid','Tepid came from Latin tepidus, “lukewarm,” related to tepere, “to be warm”; figuratively it describes weak enthusiasm or support.',[C('tepid.s1','温度','She poured out the tepid tea and made a fresh, steaming pot.','她倒掉了温温的茶，又泡了一壶热气腾腾的新茶。','tepid water/tea; slightly tepid','形容词，指略微温热、不冷不热的。','the tea is neither hot nor cold.','温度'),C('tepid.s2','反应','The plan received a tepid response from residents who wanted stronger guarantees.','居民希望得到更有力的保障，因此对这项计划反应冷淡。','a tepid response/reception; tepid support','形容词，指反应或支持不热烈的。','the residents show little enthusiasm.','反应')],M('The committee gave the proposal a tepid reception, cheering enthusiastically and demanding its immediate adoption.','The committee gave the proposal an enthusiastic reception, cheering and demanding its immediate adoption.','tepid reception表示冷淡反应，与热烈欢呼相矛盾。','meaning'),[Q(1,'Tepid tea is…','slightly warm rather than hot','frozen solid','boiling vigorously','Sense 1 describes temperature.','meaning'),Q(2,'A tepid response suggests…','little excitement or support','unanimous, passionate approval','a formal end to a railway line','Sense 2 is figurative and describes low enthusiasm.','context'),Q(1,'Which phrase is natural?','a tepid response to the proposal','a response tepidly for proposal','a tepid of response proposal','Tepid modifies response directly.','grammar'),Q(1,'Latin tepidus meant…','lukewarm','three each','a legal declaration','The English temperature sense preserves the Latin meaning.','word-formation')]);
P('term','Term came through Old French terme from Latin terminus, “boundary, limit”; it can name a technical expression, a fixed period, a condition, or the act of calling something by a name.',[C('term.s1','术语','In biology, the term “habitat” means the natural home of an organism.','在生物学中，habitat一词指生物的自然栖息地。','a technical/legal term; define a term','名词，指在某一领域有特定含义的词语。','the quoted word has a specialized definition.','术语'),C('term.s2','期限','The spring term ends with exams in late June.','春季学期在六月下旬以考试结束。','school/academic term; during the term','名词，指学年或其他固定时段中的一段。','the school year is divided into periods.','期限'),C('term.s3','条款','The contract sets out the terms of payment in its second section.','合同第二部分列明了付款条件。','terms of an agreement; agree to the terms','名词，指协议中的条件或规定。','the document specifies agreed conditions.','条款'),C('term.s4','称为','Scientists term the process “selective breeding.”','科学家把这一过程称为“选择性育种”。','term something a success; be termed','动词，指用某个名称称呼或描述某事物。','term takes an object and a name complement.','称为')],M('The contract termed the monthly payment conditions “payment schedule” in section two.','The contract terms set out the monthly payment conditions in section two.','原句把名词terms误作动词term的结构；可改成the contract terms。','grammar'),[Q(1,'In biology, habitat is a term because it is…','a word with a specialized meaning','a school-year period','a payment condition','Sense 1 is a word used in a field.','meaning'),Q(2,'The spring term refers to…','one period of the academic year','a named scientific expression','the last point of a journey','Sense 2 concerns a fixed period.','context'),Q(3,'The terms of a contract are…','its conditions and rules','the words used only in biology','the length of a railway platform','Sense 3 means contractual conditions.','meaning'),Q(4,'Scientists term a process “selective breeding” means they…','call or describe it by that name','end it at a particular place','divide a school year into parts','Term is a verb meaning call something a name.','grammar')]);
P('termagant','Termagant first named a supposed deity in medieval European romances; it later became a label for a quarrelsome, domineering person, especially a woman. The name’s deeper origin is uncertain.',C('termagant.s1','性格','In the novel, the termagant landlady berates every visitor who enters the hall.','小说里，那位泼悍的女房东一见有人进大厅就责骂。','a termagant woman; behave like a termagant','名词，指脾气暴躁、爱争吵且盛气凌人的人，常带贬义。','she repeatedly shouts at visitors.','性格'),M('The termagant quietly welcomed each guest, listened patiently, and avoided every argument.','The termagant shouted at guests and turned every visit into an argument.','termagant指争吵、盛气凌人的人，与安静耐心的行为相反。','meaning'),[Q(1,'A termagant in the novel is…','a quarrelsome, domineering person','a mild-mannered guest','a technical word in biology','The source definition describes an aggressive person.','meaning'),Q(1,'What does the landlady do?','She berates visitors','She gives each visitor a scholarship','She tests the building’s wiring','Berates means scolds, matching the example.','context'),Q(1,'Which phrase fits the word?','a termagant landlady','a termagant of quietly','termagantly landlady','Termagant is used as a noun here.','grammar'),Q(1,'The word’s earliest medieval use referred to…','a supposed deity in romances','a railway terminus','a piece of technical terminology','The personal insult developed from an older fictional name.','word-formation')]);
P('terminal','Terminal is from Latin terminalis, “of boundaries or ends,” from terminus; it names transport buildings, computer or electrical endpoints, and something final.',[C('terminal.s1','交通','Passengers waited inside the airport terminal while the storm delayed departures.','暴风雨导致航班延误，乘客在机场航站楼内等候。','airport/bus terminal; terminal building','名词，指旅客到达、出发或换乘的交通枢纽建筑。','the airport building serves passengers.','交通'),C('terminal.s2','计算机','The technician entered a command at the terminal connected to the server.','技术员在连接服务器的终端上输入了一条命令。','computer terminal; access a terminal','名词，指用于连接计算机系统的屏幕和键盘设备。','the user types a command through the device.','计算机'),C('terminal.s3','末端','The path ends at a terminal platform beside the old signal box.','小路在旧信号箱旁的尽头站台终止。','terminal point/station; terminal stage','形容词，指位于末端的；也可指疾病已到无法治愈阶段的。','the platform marks the line’s end.','末端')],M('The airport terminal is the last stop where the road ends, not a building for arriving passengers.','The airport terminal is the building where passengers arrive and depart.','terminal有交通建筑义；原句把名词义和末端形容词义混淆。','meaning'),[Q(1,'An airport terminal is…','a passenger building at an airport','a technical vocabulary list','a type of insect','Sense 1 is the transport meaning.','meaning'),Q(2,'A computer terminal lets a user…','enter commands into a computer system','wait for a flight inside the airport','cover a roof with straw','Sense 2 is an input/display device.','context'),Q(3,'A terminal point is…','the final point of a route or process','a mildly warm drink','a technical word in a subject','Sense 3 uses terminal to mean at the end.','meaning'),Q(1,'Which collocation names an airport building?','airport terminal','airport terminusly','terminal of airporting','Airport terminal is the standard compound.','collocation')]);
P('terminate','Terminate derives from Latin terminare, “to set bounds, bring to an end,” from terminus, “boundary”; it means end something or come to an end at a point.',[C('terminate.s1','结束','The company terminated the lease after the tenant stopped paying rent.','租户停止付租后，公司终止了租约。','terminate a contract/lease; terminate employment','动词，指正式结束合同、服务或关系。','the company brings the lease to an end.','结束'),C('terminate.s2','终止于','The hiking trail terminates beside a small lake in the valley.','徒步小径在山谷中的一座小湖旁结束。','road/line terminates at a point','动词，指路线或过程在某处结束。','the route reaches its endpoint.','终止于')],M('The lease terminated the company when the tenant stopped paying rent.','The company terminated the lease when the tenant stopped paying rent.','terminate在此以公司为主语、租约为宾语；原句颠倒了施事和受事。','grammar'),[Q(1,'The company terminated the lease means it…','brought the agreement to an end','extended it forever','used it as technical vocabulary','Terminate is transitive in this sense.','meaning'),Q(2,'If a trail terminates beside a lake, it…','ends there','starts there and continues forever','is a contract','Sense 2 describes where a route ends.','context'),Q(1,'Which sentence uses terminate correctly?','They terminated the contract in March.','They terminated at the contract in March.','They were terminated the contract.','The company or people terminate an agreement directly.','grammar'),Q(1,'The Latin root terminus referred to a…','boundary or end point','warm liquid','woven cloth','Terminate developed from a Latin verb built on terminus.','word-formation')]);
P('termination','Termination is formed from terminate with the noun-forming suffix -ation; it names an ending or, in a medical context, the ending of a pregnancy.',[C('termination.s1','结束','The early termination of the service contract required written notice.','提前终止服务合同需要书面通知。','termination of a contract; early termination','名词，指某项协议、服务或过程结束的行为或时点。','the service ceases before its planned end.','结束'),C('termination.s2','医疗','The clinic offers confidential counseling before a pregnancy termination.','诊所会在终止妊娠前提供保密咨询。','pregnancy termination; termination of pregnancy','名词，医学语境中指终止妊娠。','the clinic provides counseling around the medical procedure.','医疗')],M('The termination of the contract continued it unchanged for another five years.','The renewal of the contract continued it for another five years.','termination指结束；原句的后半部分描述续约而非终止。','meaning'),[Q(1,'Termination of a service contract is…','the act or point of ending it','the promise to extend it forever','a meeting at the start of a journey','Sense 1 is the general ending sense.','meaning'),Q(2,'Pregnancy termination is used in…','a medical context','a railway timetable','a classroom vocabulary list','Sense 2 is the medical use.','context'),Q(1,'Which phrase is standard?','termination of the contract','termination to the contract','terminate of contracting','Of links termination with what is ended.','grammar'),Q(1,'The suffix -ation here forms…','a noun naming an action or result','a comparative adjective','a plural verb','Termination is a noun related to the verb terminate.','word-formation')]);
P('terminology','Terminology is built from term plus -ology, a combining form for a field of study or organized body of knowledge; it means the technical words used in a subject.',[C('terminology.s1','专业词汇','The nursing course introduces medical terminology for describing symptoms and treatments.','护理课程介绍用于描述症状和治疗的医学术语。','medical/legal terminology; learn terminology','名词，指特定学科或职业使用的一套专业词汇。','the course teaches field-specific words.','专业词汇'),C('terminology.s2','用语','The report’s terminology for risk differs from the wording used by the regulator.','报告中关于风险的用语不同于监管机构采用的说法。','use/adopt terminology; terminology for a concept','名词，也指谈论某个主题时所采用的特定用语。','the two documents choose different terms.','用语')],M('The nurse learned medical terminology, a set of specialized words, by avoiding all field-specific terms.','The nurse learned medical terminology by studying the field-specific terms.','terminology本身就是一套专门用语，不能通过回避所有术语来学习。','meaning'),[Q(1,'Medical terminology is…','specialized vocabulary used in medicine','a place at the end of a bus line','a phrase meaning slightly warm','That is the field-specific vocabulary sense.','meaning'),Q(2,'A report’s terminology refers to…','the particular words it chooses for a subject','the length of the report’s printing paper','the report’s final point on a route','Sense 2 concerns wording choices.','context'),Q(1,'Which collocation is natural?','technical terminology','terminology of technically','a terminology terming','Technical commonly modifies terminology.','collocation'),Q(1,'The ending -ology commonly relates to…','a subject or organized field of knowledge','a person who is frightened','a dwelling made from poles','The compound combines term with a field-related ending.','word-formation')]);
P('terminus','Terminus is Latin for a boundary or end point; English uses it for the final station on a route and, more broadly, the final point of a journey or process.',[C('terminus.s1','终点站','The last train leaves the northern terminus shortly after midnight.','开往北部终点站的末班车在午夜刚过发车。','railway/bus terminus; arrive at the terminus','名词，指公交或铁路线路尽头的车站。','the station is where the route ends.','终点站'),C('terminus.s2','终点','The expedition’s terminus was a research camp on the glacier.','这次考察的终点是冰川上的一个研究营地。','the terminus of a route/process; reach a terminus','名词，泛指旅程或活动到达的最终地点或阶段。','the camp marks the journey’s endpoint.','终点')],M('The bus left the terminus, the station at the end of its route, and remained at its starting point.','The bus left the terminus and began its route from the final station.','terminus是线路尽头的站；离开后车辆开始行程，不是留在起点不动。','meaning'),[Q(1,'A railway terminus is…','a station at the end of a line','a list of medical terms','a colony of insects','That is the transport sense.','meaning'),Q(2,'The expedition’s terminus was…','its final destination','its first vocabulary lesson','a mild response to the plan','Sense 2 applies the end-point idea broadly.','context'),Q(1,'Which phrase is natural?','arrive at the terminus','arrive terminusly at','terminus arrive of','At introduces the station or final point reached.','collocation'),Q(1,'Latin terminus meant…','boundary or end point','woven fabric','a bird with a forked tail','The English uses preserve the Latin end-point sense.','word-formation')]);
P('termite','Termite came through French termite from Latin termes/termitis, an old name for a wood-eating insect; it is a social insect that feeds on cellulose.',C('termite.s1','昆虫','The inspector found a termite colony inside the damp wooden beam.','检查员在潮湿的木梁里发现了白蚁群。','termite colony; termite damage; wood-eating termite','名词，指以纤维素为食、常群居并会损坏木材的昆虫。','the colony is living and feeding inside timber.','昆虫'),M('The termite colony protected the wooden beam by eating nothing but metal nails.','The termite colony damaged the wooden beam while feeding on its cellulose.','白蚁取食木材中的纤维素，不以金属钉为食。','meaning'),[Q(1,'A termite is an insect that often…','feeds on cellulose and damages wood','makes a bus route end','pairs chromosomes during meiosis','That describes its source sense.','meaning'),Q(1,'Where was the colony found?','Inside a damp wooden beam','At the airport terminal','On a flat terrace','The context says it was inside the beam.','context'),Q(1,'Which phrase is natural?','termite damage to a beam','damage termite of beamly','a beam termites on damage','Termite damage names harm caused by termites.','collocation'),Q(1,'The older Latin name behind termite referred to…','a wood-eating insect','a university appointment','a period in the school year','The English word was transmitted through French from Latin insect terminology.','word-formation')]);
P('tern','Tern arrived through East Anglian dialect from a Scandinavian source, compare Danish terne and Old Norse þerna; it names a slender seabird that dives for fish.',C('tern.s1','鸟类','A tern hovered above the bay before diving sharply for a fish.','一只燕鸥在海湾上空盘旋，随后急速俯冲捕鱼。','a flock of terns; arctic tern; tern dives for fish','名词，指常在海面上空盘旋并俯冲捕鱼的细长海鸟。','the bird hovers and dives to catch prey.','鸟类'),M('The tern circled the bay to graze on grass, never approaching the water or catching fish.','The tern circled the bay and dived into the water to catch fish.','tern是捕鱼的海鸟，原句把它写成只吃草且不接近水面。','meaning'),[Q(1,'A tern is a…','slender seabird that often dives for fish','small conical dwelling','technical word for an ending','That matches the bird sense.','meaning'),Q(1,'What did the tern do in the bay?','It hovered, then dived for a fish','It built a railway station','It terminated a contract','Those actions are typical of the example’s seabird.','context'),Q(1,'Which phrase is natural?','a flock of terns','a flock ternly','tern of a flocking','A flock of is a natural group expression.','collocation'),Q(1,'The word tern entered English through…','a Scandinavian source via East Anglian dialect','Latin for a boundary','Lakota for dwelling','The historical route is Scandinavian through regional English.','word-formation')]);
P('terrace','Terrace came through French terrasse from Latin terra, “earth”; it can be a paved area beside a building, a level step on a slope, or a row of joined houses.',[C('terrace.s1','露台','They ate breakfast on the terrace overlooking the garden.','他们在俯瞰花园的露台上吃早餐。','sit/eat on a terrace; terrace overlooking a garden','名词，指建筑物旁供人使用的平坦铺面区域。','the paved outdoor area is beside the house.','露台'),C('terrace.s2','梯田','Farmers cut narrow terraces into the steep hillside to grow rice.','农民在陡峭山坡上修出狭窄梯田种稻。','terraced hillside; cut terraces into a slope','名词，指山坡上逐级修出的平地。','each level step holds a field.','梯田'),C('terrace.s3','联排住宅','The family bought a terrace on a quiet street near the station.','这家人在车站附近一条安静的街上买了一套联排住宅。','a row of terraces; terrace house','名词，指一排相连的房屋中的一栋，或观众席的高台。','the dwelling shares side walls with neighbouring houses.','住宅')],M('The family sat on the terrace, an underground railway station at the end of the route.','The family sat on the terrace, the paved outdoor area beside their house.','terrace在该句中是屋旁露台，不是终点站。','meaning'),[Q(1,'Breakfast on a terrace happens…','on a flat outdoor area beside a building','inside a computer keyboard','at the end of a railway line','Sense 1 is the outdoor sitting area.','meaning'),Q(2,'Rice terraces are…','level steps cut into a hillside','rows of houses joined together','technical vocabulary about medicine','Sense 2 is the agricultural landform.','context'),Q(3,'A terrace house is…','one home in a row of joined houses','a flat outdoor dining area only','a seabird','Sense 3 concerns connected housing.','meaning'),Q(2,'The Latin source terra meant…','earth or land','warmth','a boundary marker','Terrace is historically linked with earth and ground.','word-formation')]);
P('terrain','Terrain came from French terrain, from terre, “earth,” ultimately Latin terra; it refers to land of a particular kind or, figuratively, an area of activity or knowledge.',[C('terrain.s1','地形','The rescue team used a rope because the rocky terrain was too steep to cross safely.','岩石遍布的地形太陡，救援队用绳索确保安全通过。','rough/mountainous terrain; cross difficult terrain','名词，指某地的地貌或地表特征，尤其影响通行的部分。','the ground conditions make travel difficult.','地形'),C('terrain.s2','领域','Data privacy is familiar terrain for the lawyer, who handles these cases daily.','这名律师每天处理相关案件，因此熟悉数据隐私这一领域。','familiar/new terrain; enter uncharted terrain','名词，指一个知识、活动或经验领域。','the topic is an area of professional experience.','领域')],M('The rescue team crossed rocky terrain easily because it was a subject of legal knowledge.','The rescue team crossed rocky terrain carefully because the ground was steep and uneven.','rocky terrain指崎岖地面，不是知识领域。','meaning'),[Q(1,'Rocky terrain describes…','the physical ground and its features','a contract’s payment rules','a weak response to a proposal','Sense 1 is the landscape meaning.','meaning'),Q(2,'Familiar terrain for a lawyer is…','an area of knowledge or experience','a steep mountain slope only','a final bus station','Sense 2 is figurative.','context'),Q(1,'Which phrase is natural?','rough terrain','terrain roughnessly','rough of terraining','Rough directly modifies terrain.','collocation'),Q(1,'French terre, behind terrain, means…','earth or land','a short sharp reply','a legal witness','The landscape word derives from a word for earth.','word-formation')]);
P('terrane','Terrane is a geological term formed from terrain by analogy; it denotes a crustal fragment with a geological history distinct from adjoining areas, often bounded by faults.',C('terrane.s1','地质','The geologists mapped an ancient terrane whose rocks formed far from the present continent.','地质学家绘制了一块古老地体的地图，其岩石形成于远离现今大陆的地方。','tectonic terrane; accreted/exotic terrane','名词，指具有独特地质历史、与邻近地壳不同的一块地体。','the crustal block has a separate geological origin.','地质'),M('The terrane was an ordinary patch of identical rock with no distinct boundaries or geological history.','The terrane was a crustal block with rocks and a history distinct from its neighbours.','地质学中的terrane强调地质特征或历史与周围不同的地壳块体。','meaning'),[Q(1,'A geological terrane is…','a crustal fragment with a distinct geological history','a conical tent made of canvas','a period of academic employment','That is the specialized geology sense.','meaning'),Q(1,'Why was the mapped terrane notable?','Its rocks formed far from the present continent','It was a railway station','It was a short legal statement','The example stresses its separate geological origin.','context'),Q(1,'Which modifier is standard?','tectonic terrane','terrane of tectonicallyly','a tectonicly terrane','Tectonic is the adjective used to modify the geological noun.','grammar'),Q(1,'Terrane is formed by analogy with…','terrain','terminology','terpene','The geological term was shaped on the existing land word.','word-formation')]);
P('terrestrial','Terrestrial comes from Latin terrestris, “of the earth,” from terra, “earth”; it describes land or Earth rather than sea or space, and can name a land-dwelling creature.',[C('terrestrial.s1','地球/陆地','The probe collected terrestrial dust before it was launched into space.','探测器发射升空前采集了地球上的尘土。','terrestrial life/environment; terrestrial rather than marine','形容词，指地球上的或陆地的，与海洋、外太空相对。','the dust comes from Earth, not another world.','地球/陆地'),C('terrestrial.s2','陆生生物','The zoo moved the terrestrial tortoise to a dry enclosure away from the pond.','动物园把陆生乌龟移到了远离池塘的干燥围栏里。','terrestrial animal/species; terrestrial creature','名词，指生活在陆地上的生物；也常作形容词修饰这类生物。','the tortoise lives on land rather than in water.','陆生生物')],M('The terrestrial tortoise spent its whole life underwater among marine fish.','The terrestrial tortoise lived on land in a dry enclosure.','terrestrial指陆地生物，与终生生活在水中的海洋生物相反。','meaning'),[Q(1,'Terrestrial dust is dust…','from Earth or land','from the deep ocean only','used to end a contract','Sense 1 contrasts Earth/land with other settings.','meaning'),Q(2,'A terrestrial tortoise is…','a land-dwelling animal','a computer input device','a seabird that dives for fish','Sense 2 is about where an organism lives.','context'),Q(1,'Which contrast is natural?','terrestrial rather than marine','terrestrially than marine','marine rather than terrestrialness','Terrestrial and marine contrast land and sea.','collocation'),Q(1,'Latin terra meant…','earth','fear','a term of office','The Latin root directly names the earth.','word-formation')]);
P('terrible','Terrible comes from Latin terribilis, “causing fear,” from terrere, “frighten”; modern use commonly means very bad or unpleasant, as well as frightening.',[C('terrible.s1','糟糕','We had terrible weather, with heavy rain and strong winds all afternoon.','整个下午大雨和大风不断，天气糟透了。','terrible weather/service; feel terrible','形容词，指质量很差或令人不快的。','the weather makes the day unpleasant.','糟糕'),C('terrible.s2','可怕','The terrible explosion shattered windows several streets away.','那场可怕的爆炸震碎了几条街外的窗户。','terrible accident/threat; a terrible noise','形容词，指造成恐惧、震惊或严重危害的。','the blast is frightening and damaging.','可怕')],M('The terrible service was excellent, prompt, and pleasant in every respect.','The excellent service was prompt and pleasant in every respect.','terrible表示糟糕，不能用来褒奖优质服务。','meaning'),[Q(1,'Terrible weather is…','very unpleasant or poor','slightly warm','a final point on a route','Sense 1 describes bad quality or experience.','meaning'),Q(2,'A terrible explosion is…','frightening and potentially harmful','a quiet and harmless meeting','a helpful technical term','Sense 2 emphasizes fear or serious harm.','context'),Q(1,'Which phrase is natural?','a terrible accident','a terrible of accidently','terribly accident','Terrible is an adjective before the noun.','grammar'),Q(1,'The original Latin sense of terribilis was…','causing fear','holding a job','covering a roof with straw','The modern negative adjective descends from a fear-related source.','word-formation')]);
P('terribly','Terribly is formed from terrible plus -ly; it can mean “to an extreme degree” in conversation or describe suffering in a severe, frightening way.',[C('terribly.s1','程度','I am terribly sorry that the train was delayed by the storm.','列车因暴风雨晚点，我实在非常抱歉。','terribly sorry; terribly important','副词，口语中常用于加强程度，表示“非常”。','terribly intensifies the adjective sorry.','程度'),C('terribly.s2','严重','Several villages were terribly damaged by the flood.','洪水严重破坏了好几个村庄。','suffer terribly; be terribly affected','副词，指以严重、令人震惊的方式。','the damage is severe.','严重')],M('I am terribly sorry means I am only a little sorry and barely regret the delay.','I am terribly sorry means I am very sorry about the delay.','terribly常作程度副词表示非常，语境中不是轻微程度。','meaning'),[Q(1,'Terribly sorry usually means…','very sorry','not sorry at all','slightly warm','Sense 1 intensifies sorry.','meaning'),Q(2,'The villages were terribly damaged means…','the damage was severe','the flood was mildly pleasant','the villages were at the end of a route','Sense 2 describes severe harm.','context'),Q(1,'Which placement is natural?','terribly sorry about the delay','sorry terriblyness about the delay','terrible sorry about delayly','The adverb terribly modifies the adjective sorry.','grammar'),Q(1,'The suffix -ly in terribly forms…','an adverb','a plural noun','a past-tense verb','Terribly modifies adjectives or verbs as an adverb.','word-formation')]);
P('terrific','Terrific comes from Latin terrificus, “causing terror,” from terrere, “frighten”; English first used it for something terrifying and later developed the common positive sense “excellent.”',[C('terrific.s1','极好','The students gave a terrific performance at the spring concert.','学生们在春季音乐会上表演得非常出色。','terrific job/performance/idea; look terrific','形容词，口语中表示极好、令人赞叹的。','the performance is praised.','极好'),C('terrific.s2','强烈/巨大','A terrific wind pushed the boat away from the dock.','猛烈的大风把船从码头吹开。','terrific force/noise; a terrific impact','形容词，也可表示力量、数量或程度很大。','the wind exerts great force.','强烈/巨大')],M('The students gave a terrific performance, meaning it was dreadful and disappointed everyone.','The students gave a dreadful performance and disappointed everyone.','terrific的常见现代褒义是极好；原句把它解释成dreadful。','meaning'),[Q(1,'A terrific performance is…','excellent and impressive','poor and unpleasant','a legal document','Sense 1 is the common positive use.','meaning'),Q(2,'A terrific wind means a wind that is…','very strong','only slightly warm','completely motionless','Sense 2 conveys great force.','context'),Q(1,'Which phrase is natural?','a terrific idea','a terrificly idea','an idea terrificness','Terrific is an adjective modifying idea.','grammar'),Q(1,'The earlier Latin source of terrific meant…','causing terror','holding permanently','earth or land','The word’s older sense was fear-related before its positive use developed.','word-formation')]);
P('terrify','Terrify is from Latin terrificare, “to frighten,” related to terrere, “frighten”; it means make someone extremely afraid or threaten them into submission.',[C('terrify.s1','使害怕','The sudden crash terrified the hikers sheltering in the cave.','突然的巨响吓坏了躲在洞里的徒步者。','terrify someone; be terrified by something','动词，指使某人感到极度害怕。','the crash causes intense fear.','使害怕'),C('terrify.s2','威吓','The gang tried to terrify shopkeepers into paying protection money.','帮派试图恐吓店主交保护费。','terrify someone into silence/compliance','动词，指用威胁或暴力使某人屈服。','the threats are used to coerce compliance.','威吓')],M('The crash terrified the hikers, so they felt completely calm and unafraid.','The crash terrified the hikers, so they felt frightened and sought shelter.','terrify表示使极度害怕，和完全镇定无惧相反。','meaning'),[Q(1,'The crash terrified the hikers means it…','made them extremely afraid','made them feel pleasantly warm','ended their hiking route','Sense 1 means cause intense fear.','meaning'),Q(2,'Terrify shopkeepers into paying means…','use threats to coerce them','persuade them through friendly discussion only','describe a terraced house','Sense 2 is coercion by intimidation.','context'),Q(1,'Which construction is correct?','terrify someone into silence','terrify someone to into silent','terrify into someone silencing','Into is followed by the result or action.','grammar'),Q(1,'The Latin source terrificare meant…','to frighten','to make a boundary','to study technical vocabulary','The verb’s historical sense matches the modern fear meaning.','word-formation')]);
P('terrifying','Terrifying is the present participle adjective of terrify, formed with -ing; it describes something that causes intense fear.',C('terrifying.s1','恐惧','The terrifying drop from the narrow bridge made the hikers grip the railing.','狭窄桥面下方的陡峭落差吓得徒步者紧紧抓住栏杆。','a terrifying experience/sight; utterly terrifying','形容词，指令人极度害怕的。','the drop causes fear in the hikers.','恐惧'),M('The terrifying drop made the hikers feel perfectly safe and eager to jump.','The terrifying drop made the hikers grip the railing and step back.','terrifying描述引起恐惧的事物，与完全安心、想跳下去相反。','meaning'),[Q(1,'A terrifying drop is…','one that causes great fear','one that is slightly warm','a drop that ends a contract','The adjective describes the effect on observers.','meaning'),Q(1,'How did the hikers react?','They gripped the railing','They applauded the scenery','They began a school term','Their response shows they were afraid.','context'),Q(1,'Which phrase is natural?','a terrifying experience','a terrifyingly experience','an experience terrifyingness','Terrifying is an adjective before the noun.','grammar'),Q(1,'The ending -ing here forms…','an adjective describing what causes the feeling','a noun for a legal will','a verb in the past tense','Terrifying describes something that terrifies people.','word-formation')]);
P('terrifyingly','Terrifyingly is formed from terrifying with -ly; it means in a way that causes fear or, as an intensifier, to an alarming degree.',C('terrifyingly.s1','程度/恐惧','The truck passed terrifyingly close to the cyclist on the wet road.','卡车在湿滑路面上从骑车人身边擦过，距离近得吓人。','terrifyingly close/fast; terrifyingly realistic','副词，指令人害怕地，也常加强某种程度以表达惊人或令人担忧。','the dangerously small distance alarms the cyclist.','程度/恐惧'),M('The truck passed terrifyingly close, leaving a safe distance of several hundred metres.','The truck passed terrifyingly close, nearly brushing the cyclist.','terrifyingly close表示近得令人害怕，与相隔数百米不符。','meaning'),[Q(1,'Terrifyingly close means…','so close that it is alarming','so far away that it cannot be seen','slightly warm to the touch','The adverb intensifies close and signals danger.','meaning'),Q(1,'What made the cyclist afraid?','The truck nearly brushed past','The trip reached its terminus','A term was defined','The context describes a near collision.','context'),Q(1,'Which word does terrifyingly modify?','close','truck as a noun label','cyclist as a plural verb','It is an adverb modifying the adjective close.','grammar'),Q(1,'Terrifyingly is built by adding -ly to…','terrifying','terrorism','terrace','The suffix turns the adjective into an adverb.','word-formation')]);
P('territorial','Territorial is formed from territory with -al; it describes land or jurisdiction, and also an animal or person that guards an area as its own.',[C('territorial.s1','领土','The treaty settled the territorial dispute along the river boundary.','条约解决了沿河边界的领土争端。','territorial waters/boundary; territorial dispute','形容词，指与领土、地域管辖权有关的。','the dispute concerns who controls the land.','领土'),C('territorial.s2','护地盘','Our usually friendly dog becomes territorial when another dog enters the yard.','另一只狗进入院子时，我们平日温顺的狗会护地盘。','territorial about a space; territorial behaviour','形容词，指把某块空间视作自己的并加以防守的。','the dog defends the yard from an intruder.','护地盘')],M('The dog was territorial about the yard, welcoming every intruder and never guarding its space.','The dog was territorial about the yard, barking when another dog entered.','territorial描述守护自己空间的行为，与从不防守相反。','meaning'),[Q(1,'A territorial boundary concerns…','the limits of land under control','a school term','a set of technical words','Sense 1 is about territory and jurisdiction.','meaning'),Q(2,'A territorial dog may…','defend a space it treats as its own','avoid noticing every animal in its yard','end a route beside a lake','Sense 2 describes defensive behaviour around an area.','context'),Q(1,'Which phrase is standard?','territorial waters','territory watersly','waters territorialness','Territorial modifies waters to describe jurisdiction.','collocation'),Q(1,'The suffix -al in territorial forms…','an adjective related to territory','a person who gives evidence','a past-tense verb','Territorial means connected with a territory.','word-formation')]);
P('territory','Territory came through Old French territoire from Latin territorium, “district or land”; it means controlled land, a defended area, or a field of activity.',[C('territory.s1','领土','The island became a territory administered by the national government.','这座岛成为由中央政府管辖的领土。','national/overseas territory; territorial waters','名词，指由国家或统治者控制的区域。','the island is governed as part of a state.','领土'),C('territory.s2','活动范围','The fox marked its territory along the edge of the forest.','狐狸沿着森林边缘标记自己的活动范围。','defend/mark a territory; enter another animal’s territory','名词，指动物或人视作自己的区域。','the fox identifies and guards a home range.','活动范围'),C('territory.s3','领域','For a family doctor, preventive care is familiar territory.','对家庭医生来说，预防性护理是熟悉的领域。','familiar/uncharted territory; enter new territory','名词，指某个知识、经验或活动领域。','the doctor has experience in this subject area.','领域')],M('The fox marked its territory by mapping the national border between two countries.','The fox marked its territory by scenting trees along its home range.','动物territory是活动范围，不是国家间的国界。','meaning'),[Q(1,'A national territory is…','land controlled or administered by a state','a set of words in a science','a mild response','Sense 1 concerns land under political control.','meaning'),Q(2,'A fox marks its territory to…','identify and defend its own area','define a school term','cover a roof with straw','Sense 2 is an animal’s home range.','context'),Q(3,'Familiar territory for a doctor means…','an area of knowledge or experience','a foreign country under military control','a geological crustal fragment','Sense 3 is figurative.','meaning'),Q(1,'Which collocation is natural?','enter new territory','territory enterly new','newly territory in','Enter new territory can mean move into a new subject or area.','collocation')]);
P('terror','Terror came through Old French from Latin terror, “great fear,” related to terrere, “frighten”; it also names violence or a person used to cause fear.',[C('terror.s1','恐惧','The child hid under the table in terror when the alarm began to sound.','警报响起时，孩子吓得躲到了桌子下面。','in terror; a feeling of terror; overcome with terror','名词，指极强烈的恐惧。','the child’s hiding shows intense fear.','恐惧'),C('terror.s2','暴力/恐怖','The city lived under terror as armed groups attacked civilians at night.','武装团体夜间袭击平民，整座城市笼罩在恐怖之中。','reign of terror; spread terror; a terror to others','名词，指以暴力威胁制造恐惧的行为，也可指使人害怕者。','attacks create fear throughout the city.','暴力/恐怖')],M('The child waited in terror, feeling completely relaxed and unafraid as the alarm sounded.','The child hid in terror as the alarm sounded.','in terror表示处于极度恐惧中，与完全放松无惧相反。','meaning'),[Q(1,'The child hid in terror means the child felt…','intense fear','little interest in a subject','a warm temperature','Sense 1 describes an emotion.','meaning'),Q(2,'A city under terror may experience…','violence and threats that frighten people','a peaceful celebration only','a mild disagreement about a term','Sense 2 concerns fear produced by violence.','context'),Q(1,'Which phrase is natural?','in terror','on terrorly','terror of in','In terror is the standard phrase for experiencing fear.','collocation'),Q(1,'Latin terrere meant…','to frighten','to weave','to hold a post','Terror belongs to a family of words related to frightening.','word-formation')]);
P('terrorise','Terrorise is the British spelling of terrorize, formed from terror plus -ise; it means to frighten or coerce people through violence or repeated threats.',C('terrorise.s1','恐吓','The armed gang terrorised shopkeepers until the police increased patrols.','武装团伙不断恐吓店主，直到警方加强巡逻。','terrorise a population; terrorise someone into doing something','动词，指以暴力、威胁或持续攻击使人恐惧并屈服。','repeated threats force shopkeepers to live in fear.','恐吓'),M('The gang terrorised the shopkeepers by ensuring they felt completely safe and never threatened.','The gang terrorised the shopkeepers with repeated threats and attacks.','terrorise表示制造恐惧或威胁，与保证安全、毫无威胁相反。','meaning'),[Q(1,'To terrorise a group is to…','frighten or coerce them with threats or violence','give them permanent job security','teach them technical vocabulary','That is the verb’s meaning.','meaning'),Q(1,'Why did police increase patrols?','A gang was threatening shopkeepers','The school term had ended','A seabird was nesting','The example connects patrols with the gang’s threats.','context'),Q(1,'Terrorise and terrorize are…','British and American spellings of the same verb','different tenses with different meanings','two unrelated nouns','The s/z difference is a spelling variant by region.','grammar'),Q(1,'The suffix -ise here makes…','a verb meaning cause terror','a noun for a witness statement','an adjective meaning third','Terrorise is formed from the noun terror plus a verb-forming suffix.','word-formation')]);
P('terrorism','Terrorism combines terror with -ism, a suffix naming a practice or system; it refers to violence used to frighten people, often for political aims, and to rule through fear.',[C('terrorism.s1','政治暴力','The report examined terrorism aimed at civilians to force political change.','报告分析了以平民为目标、意图迫使政治变革的恐怖主义。','combat/prevent terrorism; terrorism against civilians','名词，指尤其针对平民、以制造恐惧并推动政治目的为手段的暴力。','violence is used to intimidate and influence politics.','政治暴力'),C('terrorism.s2','恐惧统治','The historian described state terrorism used to silence critics across the country.','历史学家描述了国家恐怖主义如何用来压制全国各地的批评者。','state terrorism; a campaign of terrorism','名词，指系统性地运用暴力与恐惧统治或攻击一群人。','violence is organized as a method of control.','恐惧统治')],M('The report called a peaceful public debate terrorism even though no threats or violence occurred.','The report distinguished peaceful debate from terrorism involving violence and intimidation.','terrorism涉及暴力或恐吓；仅有和平辩论不足以构成该词所指。','meaning'),[Q(1,'The report’s example of terrorism involves…','violence against civilians to force political change','a friendly policy debate with no threats','a railway station at the end of a line','Sense 1 includes political violence and intimidation.','meaning'),Q(2,'State terrorism is…','systematic fear and violence used by a state','a school’s technical vocabulary','a row of joined houses','Sense 2 focuses on rule through organized fear.','context'),Q(1,'Which phrase is natural?','prevent terrorism','terrorism prevently','a prevent of terrorisming','Prevent terrorism is a standard verb–object phrase.','collocation'),Q(1,'The suffix -ism often names…','a practice or system','the person who performs an action','a plural ending','Terrorism names an organized practice involving terror.','word-formation')]);
P('terse','Terse came from Latin tersus, “wiped clean, neat,” the past participle of tergere, “wipe”; it describes speech that is brief and may sound sharp.',C('terse.s1','简短生硬','His terse reply, “No,” ended the discussion before anyone could ask why.','他简短生硬地回答“不行”，谈话还没来得及追问就结束了。','a terse reply/note; terse and direct','形容词，指简短到显得冷淡、唐突或不耐烦的。','the one-word response sounds sharp.','简短生硬'),M('Her terse reply included a long, warm explanation and several pages of detail.','Her terse reply was a brief, sharp “No.”','terse指简短，常带生硬感；长篇温和解释并不符合。','meaning'),[Q(1,'A terse reply is…','brief and possibly sharp','long and full of detail','a frightening explosion','That is the source sense.','meaning'),Q(1,'Why did the discussion end?','The reply was a blunt one-word no','The route terminated at a lake','A committee received a tepid response','The context links terseness with the abrupt reply.','context'),Q(1,'Which collocation is natural?','a terse note','a tersely note','a note of terseful','Terse is an adjective modifying note.','grammar'),Q(1,'Latin tersus meant…','wiped clean or neat','third in order','a portable dwelling','The old sense of neatness developed into concise expression.','word-formation')]);
P('tertiary','Tertiary comes from Latin tertiarius, “of the third,” from tertius, “third”; it means third in order or relates to higher education and service industries.',[C('tertiary.s1','第三','The tertiary aim is to improve comfort after safety and cost have been addressed.','在解决安全和成本问题后，第三个目标是提升舒适度。','tertiary factor/aim; tertiary importance','形容词，指顺序或重要性上的第三位。','the aim comes after two others.','第三'),C('tertiary.s2','高等教育/服务业','Many students move into tertiary education after finishing secondary school.','许多学生完成中学教育后进入高等教育阶段。','tertiary education/sector; tertiary services','形容词，指中学之后的高等教育，或服务业等经济部门。','the students advance beyond secondary schooling.','高等教育/服务业')],M('Her tertiary aim was the first priority, ahead of both safety and cost.','Her primary aim was the first priority, ahead of comfort.','tertiary表示第三位，不能指第一优先事项。','meaning'),[Q(1,'A tertiary aim is…','third in order or importance','the most urgent and first','a place where a bus route ends','Sense 1 means third.','meaning'),Q(2,'Tertiary education usually follows…','secondary school','a preschool nursery only','a short technical word list','Sense 2 is the education-stage use.','context'),Q(1,'Which phrase is standard?','tertiary education','tertiary educate','education tertiarily','Tertiary is an adjective modifying education.','collocation'),Q(1,'Latin tertius meant…','third','fearful','neatly wiped','The word’s numerical origin explains its order sense.','word-formation')]);
P('terylene','Terylene is a British trade name for a polyester fibre, coined from terephthalic acid and ethylene glycol, the chemicals used to make the polymer.',C('terylene.s1','纺织','The old uniform is a cotton and terylene blend that dries quickly after washing.','这套旧制服是棉和涤纶的混纺面料，洗后干得很快。','terylene fabric/fibre; a cotton–terylene blend','名词，指一种坚韧的合成聚酯纤维或其织物。','the cloth contains the synthetic fibre.','纺织'),M('The terylene shirt was woven entirely from untreated wool and contained no synthetic fibre.','The terylene shirt was made from a synthetic polyester fibre, sometimes blended with cotton.','terylene是聚酯合成纤维，不是纯羊毛。','meaning'),[Q(1,'Terylene is a…','synthetic polyester fibre or fabric','natural wool from sheep','word for a legal witness','That is the textile sense.','meaning'),Q(1,'Why did the uniform dry quickly?','It included terylene fibre','It was made of a thick stone tile','It was a type of seabird','The context links the fabric to synthetic fibre.','context'),Q(1,'Which phrase is natural?','a cotton and terylene blend','a terylene of cottonly','blend cotton terylene to','Blend is used to describe fabrics made from two fibres.','collocation'),Q(1,'The trade name terylene draws on…','terephthalic acid and ethylene glycol','Latin for a boundary and a limit','Greek for assembly and leading','The name reflects chemicals used in making the polyester.','word-formation')]);
P('tessellation','Tessellation comes from Late Latin tessellatus, “made of small square tiles,” from tessella, “small cube”; it is a pattern of shapes covering a surface without gaps or overlaps.',C('tessellation.s1','几何/镶嵌','The floor’s tessellation uses hexagons that fit together without gaps or overlaps.','地板上的镶嵌图案由六边形组成，彼此严密拼合，没有空隙或重叠。','regular tessellation; tessellation of a plane','名词，指用多边形无缝、无重叠地铺满平面的图案或过程。','each tile meets its neighbours exactly.','几何/镶嵌'),M('The tessellation left large empty holes between every hexagon on the floor.','The tessellation fitted the hexagons together to cover the floor without gaps.','几何镶嵌的关键是铺满表面且没有空隙。','meaning'),[Q(1,'A tessellation covers a surface…','with shapes leaving no gaps or overlaps','with random holes between every tile','only with circles floating apart','That is the geometric definition.','meaning'),Q(1,'What shapes form the floor pattern?','Hexagons','Terns','Legal terms','The example names hexagons as its repeating tiles.','context'),Q(1,'Which collocation is accurate?','a tessellation of hexagons','a tessellation into fear','tessellation with a legal witness','Of introduces the shapes making up the pattern.','collocation'),Q(1,'Late Latin tessella meant…','a small square tile or cube','a university job appointment','a loud, aggressive woman','The name refers to small pieces used in mosaic work.','word-formation')]);
P('test','Test came through Old French from Latin testum, “earthen pot” used in assaying metals; the trial sense developed from checking metal in such a vessel.',[C('test.s1','测验','The class has a vocabulary test tomorrow morning.','班级明天上午有一场词汇测验。','take/pass/fail a test; test of knowledge','名词，指用问题或任务测量知识、能力的测验。','the questions assess what students know.','测验'),C('test.s2','检测','The lab ran a blood test to check for the infection.','实验室做了血液检测，以检查是否感染。','blood/safety test; conduct a test','名词，指检查机器、物质或人体状况的检测。','the sample is examined for a medical condition.','检测'),C('test.s3','检验','Engineers test the new pump under pressure before installing it.','工程师在安装前对新水泵进行加压测试。','test a device/claim; test something for a fault','动词，指通过实际使用或检查来检验某物。','the pump is checked in working conditions.','检验')],M('The lab tested the blood by never examining the sample or checking for infection.','The lab tested the blood by examining the sample for signs of infection.','test指检查或检验，不能通过完全不查看样本完成。','meaning'),[Q(1,'A vocabulary test is designed to…','measure what students know','name a row of houses','make someone feel afraid','Sense 1 is an assessment.','meaning'),Q(2,'A blood test is…','a medical examination of a sample','a school-year period','a roof covering made of reeds','Sense 2 is a diagnostic check.','context'),Q(3,'Engineers test a pump by…','checking how it works under conditions','calling it a technical term','granting it a permanent job','Sense 3 is the verb meaning examine in practice.','meaning'),Q(1,'Latin testum referred to…','an earthen vessel used to assay metals','a third-stage course','the surface pattern of tiles','The comparison with a trial arose from checking metals in a vessel.','word-formation')]);
P('testament','Testament comes from Latin testamentum, from testari, “make a will or bear witness”; it means a will, a covenant, or one of the Bible’s two divisions.',[C('testament.s1','证明','The crowded gallery is a testament to the artist’s lasting popularity.','拥挤的展厅证明这位艺术家一直很受欢迎。','a testament to someone’s success; stand as a testament','名词，指证明某事实或品质的事物。','the crowd serves as evidence of popularity.','证明'),C('testament.s2','遗嘱','Her testament leaves the cottage to her niece and the savings to charity.','她的遗嘱将小屋留给侄女，并把积蓄捐给慈善机构。','last will and testament; make a testament','名词，法律上指说明死后财产处理方式的遗嘱。','the document specifies how property is distributed.','遗嘱'),C('testament.s3','圣经','The minister read a passage from the New Testament during the service.','牧师在礼拜期间朗读了《新约》中的一段经文。','Old/New Testament; a book of the Testament','名词，指《圣经》的旧约或新约部分。','the passage comes from one division of the Bible.','圣经')],M('The gallery was a testament to her popularity, although no visitors or other evidence supported her reputation.','The crowded gallery was a testament to her popularity.','a testament to表示作为某事实的证据；拥挤的人群正好构成证据。','meaning'),[Q(1,'A crowded gallery is a testament to popularity because it…','provides evidence of that popularity','is the artist’s legal will','belongs to the Old Testament','Sense 1 means evidence or proof.','meaning'),Q(2,'A last will and testament sets out…','what happens to a person’s property after death','how to define a biology term','the route’s final station','Sense 2 is the legal document.','context'),Q(3,'The New Testament is…','one of the two main divisions of the Christian Bible','a witness’s sworn court statement','a type of textile','Sense 3 is the biblical use.','meaning'),Q(1,'Latin testari meant…','to make a will or bear witness','to weave small tiles','to terrify a crowd','The historical verb connects the legal and witness senses.','word-formation')]);
P('testifier','Testifier is formed from testify plus the agent suffix -er; it names a person who gives evidence or a formal statement in a legal case.',C('testifier.s1','法律','The testifier described what she saw before the court recessed for lunch.','法院午休前，证人陈述了自己看到的情况。','a witness/testifier; question a testifier','名词，指在法律程序中提供证据或正式事实陈述的人。','the speaker gives evidence in court.','法律'),M('The testifier refused to give any evidence but was described as the person who testified.','The testifier gave evidence about what she had seen.','testifier指提供证词的人；完全不作证与该角色相矛盾。','meaning'),[Q(1,'A testifier is someone who…','gives evidence in a legal case','writes technical terms for a textbook','ends a railway line','That is the source definition.','meaning'),Q(1,'What did the testifier do?','Described what she saw in court','Conducted a blood test','Built a tiled floor','The example directly shows testimony being given.','context'),Q(1,'Which phrase is natural?','question a testifier','a testifier of questionedly','testifier question to','A court can question a person giving evidence.','collocation'),Q(1,'The suffix -er in testifier marks…','a person who performs the action','a location where buses stop','a condition of being terrified','The suffix forms an agent noun from testify.','word-formation')]);
P('testify','Testify came through Old French from Latin testificari, “bear witness,” formed from testis, “witness,” and facere, “make”; it means give evidence or serve as evidence.',[C('testify.s1','作证','She agreed to testify in court about the night of the accident.','她同意在法庭上就事故发生当晚的情况作证。','testify in court; testify against/for someone','动词，指在法庭等正式场合陈述所知事实。','she will give a formal witness statement.','作证'),C('testify.s2','证明','The restored bridge testifies to the town’s engineering skill.','修复后的桥梁证明了这座小镇的工程技术水平。','testify to a fact/quality; evidence testifies','动词，指某事物清楚地表明一个事实或品质。','the bridge is visible evidence of skill.','证明')],M('She testified in court by keeping silent and refusing to give any account.','She testified in court by describing what she knew about the accident.','testify表示正式陈述所知事实，保持沉默不是作证。','meaning'),[Q(1,'To testify in court is to…','give a formal account of what one knows','receive a university appointment','end a route beside a lake','Sense 1 is the legal verb.','meaning'),Q(2,'The restored bridge testifies to skill means it…','provides clear evidence of the town’s skill','hides all evidence of the town’s skill','frightens the engineers into silence','Sense 2 means serve as proof.','context'),Q(1,'Which construction is standard?','testify to a fact','testify a fact to','testify for a factly','To introduces the fact or quality shown.','grammar'),Q(1,'Latin testificari meant…','to bear witness','to be third in a sequence','to wipe clean','The Latin source combines witness and doing/making.','word-formation')]);
P('testimonial','Testimonial is related to testimony, from Latin testimonium, “evidence or witness”; as a noun it is praise or a public tribute, and as an adjective it relates to such praise.',[C('testimonial.s1','推荐/表扬','The clinic displayed a testimonial from a patient who praised the nurses’ care.','诊所展示了一位患者的感谢推荐，赞扬护士的照护。','customer/patient testimonial; give a testimonial','名词，指称赞个人品质或产品的书面或口头陈述，也可指公开致敬时赠送的礼物。','the patient’s statement recommends the service.','推荐/表扬'),C('testimonial.s2','纪念/致敬','The club held a testimonial dinner to honour its retiring captain.','俱乐部举行纪念晚宴，向即将退役的队长致敬。','testimonial dinner/match; testimonial event','形容词，指与公开致敬或表扬有关的。','the dinner publicly recognizes the captain.','纪念/致敬')],M('The patient’s testimonial criticized the clinic and warned others not to use it.','The patient’s testimonial praised the clinic’s care and recommended its nurses.','testimonial在此指赞扬性陈述，与批评和劝阻相反。','meaning'),[Q(1,'A patient testimonial usually…','praises a person, service, or product','lists the terms of a legal contract','names a geological land block','Sense 1 is a statement of praise.','meaning'),Q(2,'A testimonial dinner is held to…','honour someone publicly','test a machine for faults','describe land controlled by a state','Sense 2 relates to a tribute event.','context'),Q(1,'Which phrase is natural?','a customer testimonial','a testimonial to customerly','a testimony dinnerly','Testimonial is the noun used for a recommendation.','collocation'),Q(1,'Testimonial is historically related to…','testimony meaning evidence or witness','terrace meaning a flat outdoor area','tepid meaning lukewarm','The shared root links the word with witnessing and attestation.','word-formation')]);
P('testimony','Testimony came from Latin testimonium, “evidence, witness, attestation,” from testis, “witness”; it means a sworn statement or evidence that clearly demonstrates a fact.',[C('testimony.s1','证词','Her testimony changed the case because she identified the car at the scene.','她的证词指出了现场的汽车，改变了案件走向。','give/bear testimony; witness testimony','名词，指证人在法庭上所作的陈述。','the witness provides information relevant to the case.','证词'),C('testimony.s2','证明','The repaired seawall is testimony to the engineers’ careful planning.','修复后的海堤证明了工程师周密的规划。','be testimony to something; living testimony','名词，指清楚证明某事实或品质的事物。','the wall’s survival demonstrates the quality of the work.','证明')],M('Her testimony identified the car, but she had not seen it and offered no statement to the court.','Her testimony identified the car she had seen at the scene.','testimony是陈述或证据；未看到且未作陈述与证词不符。','meaning'),[Q(1,'Court testimony is…','a witness’s formal statement','a pattern of floor tiles','a school-year period','Sense 1 is the legal evidence sense.','meaning'),Q(2,'The seawall is testimony to planning because it…','demonstrates the engineers’ skill','contains a witness’s sworn words','is a separate country’s territory','Sense 2 means evidence or proof.','context'),Q(1,'Which phrase is standard?','give testimony in court','give a testimonyly court','testimony to give at courtly','Give testimony is a standard expression.','collocation'),Q(1,'Latin testis meant…','witness','a small square tile','a frightened person','The Latin source refers to a person who bears witness.','word-formation')]);
P('testing ground','Testing ground combines test with ground; it first refers to a place where equipment or methods are tried in practice and also to a real situation that reveals their value.',[C('testing ground.s1','试验场','The army used the desert as a testing ground for its new communications vehicle.','军方把沙漠用作新型通信车辆的试验场。','a testing ground for a vehicle/technology; use a place as a testing ground','名词，指用于实际测试设备、机器或新方法的地点。','the vehicle is tried under real conditions.','试验场'),C('testing ground.s2','检验情境','The first election became a testing ground for the party’s new campaign strategy.','首次选举成为检验该党新竞选策略的现实考场。','a testing ground for an idea/policy; serve as a testing ground','名词，指能显示某计划或能力实际效果的情境。','the election reveals whether the strategy works.','检验情境')],M('The desert was a testing ground for the vehicle, but no one drove or evaluated it there.','The desert was a testing ground where engineers drove and evaluated the vehicle.','testing ground指实际检验之处；若不试用或评估，就不是其功能。','meaning'),[Q(1,'A desert testing ground is…','a place where equipment is tried in practice','a legal document for transferring property','a crowded airport building','Sense 1 is the literal test site.','meaning'),Q(2,'An election can be a testing ground for…','a campaign strategy','the temperature of tea','the final station on a rail line','Sense 2 is a real situation used to judge an idea.','context'),Q(1,'Which phrase is natural?','a testing ground for new technology','a testing ground of technologically','ground testingly new','For introduces what is being tested.','collocation'),Q(1,'The compound combines testing with…','ground, a place or setting for trials','-ology, a field of study','-al, an adjective ending','The literal image of ground extends to a proving situation.','word-formation')]);
P('tether','Tether is from an Old Norse word for a rope or chain used to tie an animal; as a noun it also means a limit on movement, and as a verb it means tie with such a line.',[C('tether.s1','系绳','The goat pulled against its tether when it saw grass beyond the fence.','山羊看到围栏外的草时，拽着系绳往前拉。','a dog/horse tether; tie an animal to a tether','名词，指把动物系在固定处的绳或链，也可泛指行动限制。','the line keeps the goat from wandering away.','系绳'),C('tether.s2','拴住','The handlers tethered the horses to a rail before opening the stable doors.','饲养员打开马厩门前先把马拴在栏杆上。','tether an animal to a post/rail; be tethered','动词，指用系绳把动物或物体拴在固定点附近。','the rail prevents the horses from moving away.','拴住')],M('The handlers tethered the horses to the rail so that they could wander freely across the road.','The handlers tethered the horses to the rail to keep them from wandering onto the road.','tether表示拴住并限制移动，不能用来放任马匹自由乱跑。','meaning'),[Q(1,'A goat’s tether is…','a line that keeps it near a fixed point','a set of subject-specific words','a tiled geometric pattern','Sense 1 is the rope or chain meaning.','meaning'),Q(2,'The handlers tethered the horses by…','tying them to a rail','letting them run across the road','ending the stable lease','Sense 2 is the verb meaning fasten with a tether.','context'),Q(1,'Which construction is correct?','tether the horse to a rail','tether the horse at a rail to','tether to the horse a railly','To identifies the point where the animal is tied.','grammar'),Q(1,'The older Norse source of tether referred to…','a rope or animal tie','a courtroom witness','a bus terminal','The borrowed word originally named an animal tether.','word-formation')]);
P('text','Text comes through Old French texte from Latin textus, “written work or texture,” from texere, “weave”; it names written words, a study passage or phone message, and the act of messaging.',[C('text.s1','正文','The editor corrected the text but left the illustrations unchanged.','编辑修改了正文，但没有改动插图。','text of a book; edit/print the text','名词，指书、文章或文件中的文字内容，与图片相对。','the editor changes words rather than pictures.','正文'),C('text.s2','短信/学习文章','I sent my sister a text to say that the train would arrive late.','我给姐姐发了条短信，告诉她火车会晚点。','send/receive a text; a text message','名词，指手机短信，也可指供学习的短文。','the message is sent by phone.','短信/学习文章'),C('text.s3','发短信','Text me when you reach the station and I will meet you outside.','你到车站时给我发短信，我会在外面接你。','text someone; text a message to a friend','动词，指用手机发送文字信息。','text takes the recipient as its object.','发短信')],M('I texted my sister a text by sending no written message or phone message at all.','I texted my sister to tell her the train would be late.','text作动词指发送文字消息；完全没有发送消息与该动作矛盾。','meaning'),[Q(1,'The text of a book means…','its written words rather than its pictures','the author’s employment period','a flock of seabirds','Sense 1 is the written-content meaning.','meaning'),Q(2,'She sent a text to her sister by…','sending a short phone message','editing a legal will','covering a roof with reeds','Sense 2 is a message sent by phone.','context'),Q(3,'Text me when you arrive means…','send me a written phone message','read the book’s main body aloud','test the station’s safety','Sense 3 is the verb.','meaning'),Q(1,'Latin texere, behind text, meant…','to weave','to frighten','to hold a position','The metaphor links arranging written words with weaving.','word-formation')]);
P('textbook','Textbook is a transparent compound of text and book; it names a standard instructional book and, figuratively, an example showing a typical pattern.',[C('textbook.s1','教材','The chemistry textbook explains each experiment before the students enter the lab.','化学教材在学生进入实验室前讲解每项实验。','a school/chemistry textbook; write a textbook','名词，指系统介绍某学科知识、供学生学习的书。','the book teaches a subject.','教材'),C('textbook.s2','典型范例','The quick recovery was a textbook example of how early treatment can help.','迅速康复是早期治疗有益的典型例证。','a textbook example/case; textbook performance','形容词，指完全符合典型特征的。','the case illustrates the usual pattern.','典型范例')],M('The chemistry textbook was a standard student book, but it contained no teaching material and covered no subject.','The chemistry textbook presented organized lessons in the subject.','textbook作为教材应包含供学习的学科内容。','meaning'),[Q(1,'A chemistry textbook is…','a book that teaches chemistry','a terminal at an airport','a sworn statement in court','Sense 1 is the instructional book.','meaning'),Q(2,'A textbook example is…','a clear, typical illustration of a pattern','an example with no relevant features','a school-year period','Sense 2 means exemplary or typical.','context'),Q(1,'Which phrase is natural?','a biology textbook','a textbook biologically','a book textbook ofly','Textbook is the standard compound noun.','collocation'),Q(1,'Textbook is formed from…','text and book','terror and -ism','earth and a boundary','The compound names a book of instructional text.','word-formation')]);
P('textile','Textile comes from Latin textilis, “woven,” from texere, “weave”; as a noun it refers to cloth or woven/knitted goods, and as an adjective to cloth production.',[C('textile.s1','织物','The factory exports textiles made from cotton, wool, and recycled fibres.','工厂出口由棉、羊毛和再生纤维制成的纺织品。','textile industry; synthetic/natural textiles','名词，指织造或针织而成的布料及纺织品。','the goods are made from fibres.','织物'),C('textile.s2','纺织的','She enrolled in a textile design course focused on sustainable fabrics.','她报名参加了一门专注于可持续面料的纺织设计课程。','textile design/production; textile machinery','形容词，指与纺织品或纺织制造有关的。','the course concerns fabric design.','纺织的')],M('The textile factory exported fibres before they were woven or knitted into any cloth.','The textile factory exported cloth and goods made from woven fibres.','textile作为名词指织造或针织后的布料与制品。','meaning'),[Q(1,'Textiles are…','cloth or goods made by weaving or knitting','technical terms used only in medicine','land at the end of a route','That is the noun sense.','meaning'),Q(2,'A textile design course studies…','the design of fabrics','the legal rules of a contract','the sound of the th digraph','Sense 2 uses textile as an adjective.','context'),Q(1,'Which phrase is standard?','textile industry','industry textilingly','textile of industrying','Textile commonly modifies industry.','collocation'),Q(1,'Latin textilis meant…','woven','third','frightening','The Latin adjective came from a verb meaning weave.','word-formation')]);
P('textural','Textural is formed from texture plus -al; it means concerned with the tactile or visual surface quality of a material, artwork, writing, or music.',C('textural.s1','质感','The designer used a textural contrast between rough linen and smooth glass.','设计师在粗糙亚麻布和光滑玻璃之间营造出质感对比。','textural quality/contrast; textural detail','形容词，指与表面触感、视觉质地或艺术作品的肌理有关。','the two materials feel and look different.','质感'),M('The textural contrast was obvious because the linen and glass felt exactly alike.','The textural contrast was obvious because the linen felt rough while the glass felt smooth.','textural contrast强调可感知的质地差异，而不是完全相同。','meaning'),[Q(1,'A textural contrast concerns…','a difference in surface feel or appearance','a third-ranked goal','the end of a contract','That is the adjective’s meaning.','meaning'),Q(1,'What created the contrast?','Rough linen and smooth glass','Two identical smooth surfaces','A bird diving for fish','The example pairs materials with different textures.','context'),Q(1,'Which phrase is natural?','textural detail in a painting','texturally detail in painting','detail of texturalnessly','Textural is an adjective modifying detail.','grammar'),Q(1,'Textural is formed from…','texture plus the adjective suffix -al','test plus the noun suffix -imony','terror plus the verb suffix -ise','The suffix makes an adjective meaning related to texture.','word-formation')]);
P('texture','Texture derives from Latin textura, “weaving,” from texere, “weave”; it describes how a surface feels, how food feels in the mouth, or how parts are arranged in art and natural materials.',[C('texture.s1','表面触感','The silk has a smooth texture, unlike the rough canvas beside it.','这块丝绸质地光滑，与旁边粗糙的帆布不同。','smooth/rough texture; texture of a surface','名词，指物体表面触摸起来的质感。','the contrast can be felt by hand.','表面触感'),C('texture.s2','食物/结构','The soup’s creamy texture comes from the beans blended into the broth.','这道汤的奶油般口感来自打入汤汁的豆子。','creamy/grainy texture; texture of music/rock','名词，也指食物的口感或音乐、岩石等部分的组织方式。','blending the beans changes how the soup feels in the mouth.','食物/结构')],M('The soup had a creamy texture, although it felt dry and gritty in every spoonful.','The soup had a smooth, creamy texture in every spoonful.','creamy texture表示口感细滑，与干涩粗糙相矛盾。','meaning'),[Q(1,'A smooth texture describes…','how a surface feels when touched','a legal witness statement','a route’s final station','Sense 1 is tactile surface quality.','meaning'),Q(2,'The soup’s texture refers to…','how the food feels in the mouth','its position on a map','a school’s academic term','Sense 2 is the food-quality sense.','context'),Q(1,'Which phrase is natural?','the texture of the fabric','the fabric texturely of','a texture fabric ofing','Of links texture to the surface being described.','grammar'),Q(1,'Latin textura was related to…','weaving','frightening','a third place in sequence','The word developed from a Latin term for weaving or construction.','word-formation')]);
P('textured','Textured is the past participle of texture used adjectivally; it describes a surface with a noticeable pattern or a work rich in tactile or stylistic variation.',C('textured.s1','表面图案','The textured plaster wall hides small marks and gives the room a handmade look.','有纹理的灰泥墙遮住了细小痕迹，让房间显得手工感十足。','textured fabric/paper/plaster; lightly textured','形容词，指表面具有明显纹路或起伏的。','the wall’s surface is patterned rather than flat.','表面图案'),M('The textured plaster was perfectly smooth and had no pattern or surface variation.','The textured plaster had a raised surface pattern that softened the small marks.','textured表示有可察觉的纹理，与完全平滑无纹路相反。','meaning'),[Q(1,'Textured plaster has…','a noticeable surface pattern or relief','no variation and a perfectly flat surface','a legal clause','That is the adjective’s meaning.','meaning'),Q(1,'Why did the wall look handmade?','Its textured finish showed surface variation','It was a railway terminus','It was made from seaweed','The texture gives the wall a crafted appearance.','context'),Q(1,'Which phrase is natural?','textured paper','paper texturely','a texture papered','Textured is an adjective modifying paper.','grammar'),Q(1,'Textured is formed from…','texture with the participial suffix -ed','text with -ology','tertiary with -ism','The ending creates an adjective describing a surface state.','word-formation')]);
P('th','English th is a digraph for the sounds in think and this; the same letter pair also appears as the ordinal ending in words such as fourth and twelfth. The spelling replaced the older letters thorn and eth in much later writing.',[C('th.s1','字母组合','In the word “think,” th represents the voiceless sound /θ/.','在think一词中，th表示清辅音/θ/。','the th sound; pronounce th in “think”','名词，指英语字母组合th，可表示think中的/θ/或this中的/ð/。','the example isolates the spelling-to-sound relation.','字母组合'),C('th.s2','序数词词尾','The letters th mark the ordinal ending in “fourth” and “twelfth.”','th在fourth和twelfth中标记序数词词尾。','the -th ending; add th to form an ordinal','名词，指序数词中如fourth、twelfth所含的-th后缀。','the ending marks order rather than a cardinal number.','序数词词尾')],M('In “think,” the letters th represent the vowel sound /aɪ/.','In “think,” the letters th represent the voiceless consonant /θ/.','think中的th表示辅音/θ/，不是元音/aɪ/。','meaning'),[Q(1,'In “think,” th represents…','the voiceless consonant /θ/','a long vowel sound','a past-tense ending','Sense 1 concerns the digraph’s sound.','meaning'),Q(2,'In “twelfth,” -th is…','an ordinal-number ending','a plural marker','a noun meaning fear','Sense 2 is the ordinal suffix.','context'),Q(1,'Which word begins with voiced /ð/?','this','think','thin','This has the voiced th sound, unlike think and thin.','word-choice'),Q(1,'Older English writing used letters such as…','thorn and eth for these sounds','Latin numerals instead of all consonants','the ending -ology for ordinals','The digraph displaced older special letters in later spelling.','word-formation')]);
P('than','Than descends from Old English þanne/þonne, a Germanic comparative particle; it introduces the second person or thing in a comparison.',C('than.s1','比较','The new bridge is longer than the old one, but it carries fewer cars.','新桥比旧桥长，但承载的汽车更少。','taller/older/more than; rather than','介词/连词，用于引出比较中的另一方。','the old bridge is the comparison standard.','比较'),M('The new bridge is longer then the old one in a direct comparison.','The new bridge is longer than the old one.','比较级longer后用than引出比较对象；then表示时间或顺序。','grammar'),[Q(1,'In “longer than the old one,” than introduces…','the standard being compared with','the result of a test','the end of a railway line','Than links the two sides of a comparison.','grammar'),Q(1,'Which bridge is longer in the example?','The new bridge','The old bridge','Neither has a length','The sentence explicitly says the new one is longer.','context'),Q(1,'Which spelling belongs in a comparison?','than','then','thens','Than is the comparative word; then usually concerns time or sequence.','grammar'),Q(1,'Than descends from…','an Old English comparative particle','Latin for a square tile','a Lakota word for dwelling','Its inherited function is to introduce a comparison.','word-formation')]);
P('thank','Thank comes from Old English thancian, related to thanc, “thought, gratitude”; as a verb it expresses gratitude, and as a noun it can mean an expression of gratitude.',[C('thank.s1','表达感谢','I thanked the nurse for explaining the medicine schedule so clearly.','我感谢护士把服药时间表解释得如此清楚。','thank someone for something; thank someone warmly','动词，指向某人表达感激。','the speaker acknowledges the nurse’s help.','表达感谢'),C('thank.s2','谢意','She sent a handwritten thank after the neighbours brought dinner.','邻居们送来晚餐后，她寄去了一封手写的谢函。','a thank-you; a word of thanks','名词，指表示感激的话语或行为。','the note expresses gratitude.','谢意')],M('I thanked the nurse for her help by telling her that I was angry about the explanation.','I thanked the nurse for her help and said her explanation was clear.','thank表示表达感激，抱怨并生气不是感谢。','meaning'),[Q(1,'To thank the nurse is to…','express gratitude for her help','test her medical knowledge','end her work contract','Sense 1 is the verb.','meaning'),Q(2,'A handwritten thank is…','a written expression of gratitude','a route’s final station','a wool fabric','Sense 2 is a noun for a grateful expression.','context'),Q(1,'Which pattern is standard?','thank someone for help','thank for someone help','thank someone of helpingly','Thank takes the person as object and for the reason.','grammar'),Q(1,'Old English thanc was associated with…','thought or gratitude','a tiled mosaic','a bird’s forked tail','Thank is historically related to a word for gratitude or thought.','word-formation')]);
P('thankful','Thankful combines thank with -ful, “full of”; it describes gratitude for kindness or relief that a bad outcome has been avoided.',[C('thankful.s1','感激','We are thankful for the volunteers who repaired the playground fence.','我们感谢修好操场围栏的志愿者。','thankful for someone/something; feel thankful','形容词，指因受到帮助或善意而感激的。','the volunteers performed a helpful act.','感激'),C('thankful.s2','庆幸','She was thankful to be home before the icy roads became dangerous.','她庆幸自己在道路结冰变得危险前回到了家。','thankful to be safe/alive; thankful that','形容词，指对避免坏事或脱离危险感到庆幸的。','she avoided the dangerous journey.','庆幸')],M('We were thankful for the volunteers, so we complained that their repair work was worthless.','We were thankful for the volunteers and praised their helpful repair work.','thankful表达感激，与贬低帮助者的行为相反。','meaning'),[Q(1,'Thankful for the volunteers means…','grateful because of their help','angry that they offered help','uncertain about a legal term','Sense 1 is gratitude.','meaning'),Q(2,'She was thankful to be home means she…','felt relieved to have avoided danger','wanted the roads to become icy','was granted permanent employment','Sense 2 is relief about a good outcome.','context'),Q(1,'Which construction is correct?','thankful for the help','thankful of the helply','thankful the help for','For introduces the person or thing one appreciates.','grammar'),Q(1,'The suffix -ful means…','full of or characterized by','without','the person who performs an action','Thankful describes someone full of gratitude.','word-formation')]);
P('thankfulness','Thankfulness is formed from thankful plus -ness, turning the adjective into a noun for the feeling of gratitude.',C('thankfulness.s1','感恩','Her note expressed thankfulness for the neighbours who watched her children.','她在便条中表达了对照看孩子的邻居的感激之情。','express/show thankfulness; a feeling of thankfulness','名词，指对他人所做善事心存感激的情感。','the writer feels grateful for practical help.','感恩'),M('His thankfulness for the help meant he felt no gratitude and resented the neighbours.','His thankfulness for the help showed that he felt grateful to the neighbours.','thankfulness就是感激之情，与毫无感激和怨恨相反。','meaning'),[Q(1,'Thankfulness is…','the feeling of being grateful','a period of school','a kind of roof covering','That is the noun meaning.','meaning'),Q(1,'Why was she thankful?','Neighbours watched her children','The station reached its terminus','She took a vocabulary test','The note gives the help she appreciated.','context'),Q(1,'Which phrase is natural?','express thankfulness for help','thankfulness expressingly help','thankfulness of to helping','For introduces what the gratitude concerns.','grammar'),Q(1,'The suffix -ness changes thankful into…','a noun naming a state or feeling','a comparative conjunction','a verb meaning frighten','Thankfulness names the state of being thankful.','word-formation')]);
P('thanks','Thanks is the plural noun from thank and also the conventional expression used to thank someone; it can name gratitude in a book or a religious act of giving thanks.',[C('thanks.s1','致谢用语','“Thanks for carrying the boxes upstairs,” Mira said to her neighbour.','米拉对邻居说：“谢谢你把箱子搬上楼。”','thanks for your help; say/give thanks','感叹用语/名词，指表示感谢的话语。','the speaker acknowledges a helpful action.','致谢用语'),C('thanks.s2','谢意','He expressed his thanks to everyone who contributed to the community fund.','他向所有为社区基金捐款的人表达了谢意。','express/offer one’s thanks; with thanks to','名词，指对他人的感激之情。','he feels grateful for their contributions.','谢意'),C('thanks.s3','致谢部分','The book’s final pages include thanks to the translators and editors.','书的最后几页列出了对译者和编辑的致谢。','acknowledgements/thanks section; give thanks to contributors','名词，指书籍或演讲中感谢帮助者的部分。','the section names people who helped.','致谢部分'),C('thanks.s4','宗教感恩','The family said a prayer of thanks after the harvest was safely stored.','收获的粮食安全入仓后，一家人做了感恩祷告。','a prayer of thanks; give thanks for a blessing','名词，指向上帝表达感恩的行为。','the prayer expresses gratitude for the harvest.','宗教感恩')],M('“Thanks for your help,” she said while insisting that she felt no gratitude at all.','“Thanks for your help,” she said sincerely after receiving assistance.','thanks表达谢意；若明确否认任何感激，表达就自相矛盾。','meaning'),[Q(1,'“Thanks for carrying the boxes” is…','a way to express gratitude','a formal name for a railway station','a word for fear','Sense 1 is the familiar expression.','meaning'),Q(2,'He expressed his thanks means he…','showed gratitude to contributors','refused to acknowledge them','tested the community fund','Sense 2 names the feeling or expression of gratitude.','context'),Q(3,'A book’s thanks section usually…','acknowledges people who helped','lists its technical vocabulary only','describes the weather','Sense 3 refers to acknowledgements.','meaning'),Q(4,'A prayer of thanks is…','a religious expression of gratitude','a sworn statement in court','a flat area cut into a hill','Sense 4 is the religious act.','context')]);
P('Thanksgiving','Thanksgiving is the compound thank + giving, literally the act of giving thanks; it names a public holiday and also a religious service or act of gratitude.',[C('Thanksgiving.s1','节日','The family will travel to Boston for Thanksgiving and share dinner with their cousins.','一家人将前往波士顿过感恩节，与表亲共进晚餐。','Thanksgiving dinner/holiday; celebrate Thanksgiving','专有名词，指以感恩和家庭聚餐为特色的公共节日。','the family gathers for the holiday meal.','节日'),C('Thanksgiving.s2','宗教感恩','The village held a thanksgiving service after the storm spared the harvest.','风暴没有损害收成后，村里举行了感恩礼拜。','a thanksgiving service; a day of thanksgiving','名词，指宗教礼拜或表达感恩的行为。','the service thanks God for the spared crop.','宗教感恩')],M('They celebrated Thanksgiving by cancelling the meal and refusing to acknowledge anything they appreciated.','They celebrated Thanksgiving with a shared meal and expressions of gratitude.','Thanksgiving以感恩为核心，完全拒绝表达感激与其名称及语境相矛盾。','meaning'),[Q(1,'Thanksgiving in the family example is…','a public holiday celebrated with gratitude and a meal','a technical word in biology','a kind of textile','Sense 1 is the holiday.','meaning'),Q(2,'A thanksgiving service is…','a religious act expressing gratitude','a standard school examination','a route’s end point','Sense 2 concerns worship or giving thanks.','context'),Q(1,'Which phrase is natural?','Thanksgiving dinner','Thanksgivingly dinner','a dinner of Thanksgivinging','Thanksgiving modifies dinner as a holiday name.','collocation'),Q(1,'The compound Thanksgiving literally combines…','thank and giving','terror and a boundary','text and book','The name refers to the act of giving thanks.','word-formation')]);
P('that','That comes from Old English þæt, an inherited Germanic demonstrative; it points to a known thing, refers back to something, introduces a clause, or marks degree.',[C('that.s1','指示限定','That book belongs to the library, not to me.','那本书属于图书馆，不是我的。','that book/person; those books','限定词，用于指称离说话者较远或双方已知的人或物。','that specifies a particular book.','指示限定'),C('that.s2','回指','“The train is cancelled.” “That is what the notice says.”','“火车取消了。”“那就是通知上写的内容。”','that is true; remember that','代词，指代刚提到的事情。','that stands for the cancellation just mentioned.','回指'),C('that.s3','引导从句','I know that the train leaves at six because I checked the timetable.','我知道火车六点发车，因为我查过时刻表。','know/think/say that; the fact that','连词，引导补充说明内容的从句。','the clause gives the content of what I know.','引导从句'),C('that.s4','程度','The box is not that heavy, so one person can carry it.','箱子没那么重，一个人就能搬。','not that bad/big; not so ... that','副词，表示“那么、那样”，用于说明程度。','that modifies the degree of heavy.','程度')],M('I know that the train leaves at six means I have no idea when it leaves.','I know that the train leaves at six means I am certain of its departure time.','know that引出所知道的内容；原句把确定知道曲解为完全不知道。','meaning'),[Q(1,'In “That book is mine,” that…','points to a particular book','introduces a reason clause','means very or extremely','Sense 1 is demonstrative.','meaning'),Q(2,'In “That is what the notice says,” that refers to…','the cancellation just mentioned','a book far away','the degree of heaviness','Sense 2 points back to prior information.','context'),Q(3,'In “I know that the train leaves at six,” that…','introduces the content of what I know','modifies the noun train','marks a question','Sense 3 introduces a clause.','grammar'),Q(4,'“The box is not that heavy” means it is…','not so heavy to that degree','the heaviest box possible','a known box far away','Sense 4 is the degree adverb.','meaning')]);
P('that is','That is is a fixed clarifying expression built from the demonstrative that and the verb is; it introduces a restatement or a clearer explanation, often abbreviated i.e.',[C('that is.s1','换言解释','The meeting is brief, that is, it will last only twenty minutes.','会议很短，也就是说，只持续二十分钟。','that is to say; that is, ...','插入语，用来换一种更清楚或更具体的说法解释前文。','the following words explain “brief.”','换言解释'),C('that is.s2','补充说明','She is the sole candidate, that is, no one else applied for the post.','她是唯一候选人，也就是说，没有其他人申请这个职位。','that is; or, that is to say','连接表达，用于把同一事实用另一种方式说明。','the second clause restates what sole candidate means.','补充说明')],M('The meeting is brief, that is, it will last for three full weeks.','The meeting is brief, that is, it will last only twenty minutes.','that is后面的解释应阐明brief，而不是给出相反的长时间。','meaning'),[Q(1,'In “brief, that is, twenty minutes,” that is…','clarifies what brief means','introduces a contrast unrelated to the meeting','marks a route’s endpoint','It restates the idea more specifically.','meaning'),Q(2,'“The sole candidate, that is, no one else applied” means…','only one person applied','several people applied','the candidate held a university tenure','The second clause explains sole.','context'),Q(1,'Which punctuation commonly surrounds parenthetical that is?','commas','a question mark inside each word','a hyphen between that and is','Commas set off the explanatory phrase.','grammar'),Q(1,'The expression is built from…','the demonstrative that plus the verb is','the noun term plus -ology','thaw plus -ed','The phrase is a transparent fixed restatement expression.','word-formation')]);
P('that which','That which combines the demonstrative that with the relative pronoun which; the formal phrase means “the thing or things that” and refers to something already mentioned.',[C('that which.s1','正式指代','She kept that which was useful and donated the rest of the supplies.','她留下有用的东西，把其余物资捐了出去。','that which is needed; that which was mentioned','正式表达，指“所……的东西”，可作句子中的名词性成分。','the phrase refers to the useful items.','正式指代'),C('that which.s2','所需之物','The guide explains how to obtain that which visitors need for the hike.','指南说明了如何取得游客徒步所需的物品。','provide that which is required; retain that which matters','正式表达，泛指某类所需要或刚提到的事物。','that which visitors need means the needed supplies.','所需之物')],M('Keep that which is useful means keep nothing useful and discard every useful item.','Keep that which is useful means retain the useful items and discard the rest.','that which is useful指有用的东西，原句把保留和丢弃关系颠倒。','meaning'),[Q(1,'“That which was useful” means…','the thing or things that were useful','the day immediately before','a person charged with a crime','That which is a formal relative phrase.','meaning'),Q(2,'What did the guide explain how to obtain?','the supplies visitors need','a bus terminal','technical textile terms','The example identifies the needed hiking items.','context'),Q(1,'Which phrase is the more formal equivalent of “what is needed”?','that which is needed','that is which need','which that is needing','That which functions as a noun phrase meaning the thing that.','grammar'),Q(1,'That which is formed from…','that plus the relative pronoun which','thank plus the noun ending -ness','the article plus a plural verb','The phrase combines a demonstrative with a relative pronoun.','word-formation')]);
P('thatch','Thatch comes from Old English þæc, “roof covering,” related to a Germanic verb meaning cover; it names straw or reeds on a roof, a thick mass of hair, or the act of roofing with that material.',[C('thatch.s1','屋顶材料','The cottage has a thatch of reeds that must be repaired before winter.','小屋屋顶铺着芦苇茅草，冬天前必须修补。','a thatch roof; roof a house with thatch','名词，指用稻草、芦苇等铺成的屋顶覆盖物。','the reeds protect the cottage from weather.','屋顶材料'),C('thatch.s2','浓密头发','A thatch of silver hair fell over the old actor’s forehead.','一头浓密的银发垂在老演员的额头上。','a thatch of hair; thick thatch','名词，非正式地指覆盖头部的一大蓬浓密头发。','the hair forms a thick covering.','浓密头发'),C('thatch.s3','铺茅草','Local builders thatched the roof with reeds cut from the marsh.','当地工匠用从沼泽割来的芦苇给屋顶铺茅草。','thatch a roof; thatch a cottage','动词，指用稻草、芦苇等材料覆盖屋顶。','the builders apply reeds as roofing.','铺茅草')],M('They thatched the cottage roof by removing its reeds and leaving the beams uncovered.','They thatched the cottage roof with fresh reeds to keep out the rain.','thatch作动词是用茅草等覆盖屋顶，不是拆去覆盖物。','meaning'),[Q(1,'Roof thatch is…','straw or reeds used as a covering','a metal computer keyboard','the final point of a journey','Sense 1 is roofing material.','meaning'),Q(2,'A thatch of silver hair is…','a thick mass of hair','a religious service','a school test','Sense 2 is an informal figurative use.','context'),Q(3,'To thatch a roof is to…','cover it with straw or reeds','remove its covering','examine it for a fault','Sense 3 is the verb.','meaning'),Q(1,'The Old English source þæc referred to…','a roof covering','a formal clause','a person on trial','The original noun was the roofing material.','word-formation')]);
P('thaw','Thaw comes from Old English þawian, “reduce from frozen to liquid,” from a Germanic verb; it names melting ice and can also describe relations becoming less tense.',[C('thaw.s1','融化','The spring thaw sent meltwater rushing down from the snow-covered hills.','春季解冻使融水从积雪覆盖的山丘上奔流而下。','spring thaw; a thaw sets in','名词，指冰雪因天气转暖而融化的过程。','the warmer weather melts snow into water.','融化'),C('thaw.s2','解冻','The lake ice thaws by early March when the daytime temperature rises.','白天气温升高后，湖面冰层到三月初便会融化。','ice/snow thaws; thaw frozen food','动词，指冰雪或冷冻物在温度上升时变成液体或恢复柔软。','the ice changes from solid to liquid.','解冻'),C('thaw.s3','缓和','Relations between the rival firms began to thaw after they agreed to share the research costs.','竞争公司同意分担研究费用后，双方关系开始缓和。','relations thaw; a thaw in relations','动词，指紧张或冷淡的关系变得友好一些。','the agreement eases the tension.','缓和')],M('The ice thawed as temperatures rose, becoming harder and more solid each afternoon.','The ice thawed as temperatures rose and gradually became liquid.','thaw指冰受热融化，与变得更坚硬、更凝固相反。','meaning'),[Q(1,'A spring thaw is…','the melting of ice and snow','a time when a school semester starts','a group of people on trial','Sense 1 is the noun for melting.','meaning'),Q(2,'When lake ice thaws, it…','melts as the temperature rises','freezes into thicker ice','turns into a textile fibre','Sense 2 is the literal verb.','context'),Q(3,'Relations began to thaw means they…','became less tense and more friendly','became colder and more hostile','reached the end of a route','Sense 3 is figurative.','meaning'),Q(1,'Old English þawian meant…','to reduce something from frozen to liquid','to name someone a witness','to cover a roof','The historical sense matches the melting meaning.','word-formation')]);
P('the','The developed from Old English demonstrative forms and is used before a noun when a particular person or thing is identifiable, for a class as a whole, or for unique things and superlatives.',[C('the.s1','特指','Please close the door beside the kitchen; the front door can stay open.','请关上厨房旁边那扇门；前门可以开着。','the door we discussed; the person at the desk','定冠词，用在说话双方能确定所指对象的名词前。','the identifies one specific door.','特指'),C('the.s2','类别泛指','The whale is a mammal, although it lives in the ocean.','鲸属于哺乳动物，尽管它生活在海洋里。','the whale as a species; the elderly','定冠词，可与单数名词连用来泛指整个类别。','the whale represents the species generally.','类别泛指'),C('the.s3','独一/最高级','The sun rises in the east, and this is the tallest building in town.','太阳从东方升起，这是镇上最高的建筑。','the sun/moon; the best/first/largest','定冠词，用于独一无二的事物以及最高级、序数等结构。','the sun is unique and tallest marks a superlative.','独一/最高级')],M('I opened the door beside the kitchen, although neither speaker could identify which door was meant.','I opened the kitchen door we had agreed to use.','此处the标记双方可以识别的特定门；若无法确定所指，表达不成立。','meaning'),[Q(1,'In “close the door beside the kitchen,” the signals…','a particular door the listener can identify','any door in the world with no shared context','a plural number','Sense 1 is specific reference.','meaning'),Q(2,'“The whale is a mammal” uses the to…','talk about the whole species','identify one pet whale only','mark a verb’s past tense','Sense 2 is generic singular reference.','context'),Q(3,'Why say “the sun”?','There is one unique sun in our sky','The sun was already mentioned in the same sentence','Sun is a plural noun','Sense 3 covers unique referents.','meaning'),Q(1,'Which phrase normally takes the?','the tallest building','a tallest building','tallest the building','Superlatives are commonly used with the.','grammar')]);
P('the accused','The accused is a substantivized form of accuse plus -ed; in legal English it means the person or people formally charged with a crime.',[C('the accused.s1','被告','The accused denied the charge and asked the judge to review the evidence.','被告否认指控，并请求法官审查证据。','the accused person; the accused denied/was charged','名词短语，指在刑事案件中受到指控并受审的一个人。','one defendant is answering a criminal charge.','被告'),C('the accused.s2','被告群体','The accused are due to appear in court together next month.','被告们定于下个月一同出庭。','the accused are; all of the accused','名词短语，可集体指同一案件中受到指控的多个人。','the plural verb and together show several defendants.','被告群体')],M('The accused were charged in the case, but the sentence says each person had never faced any accusation.','The accused were charged in the case and will appear before the judge.','the accused指受到指控的人；声称他们没有受到任何指控与词义冲突。','meaning'),[Q(1,'The accused in a trial is…','the person charged with a crime','the judge who hears the case','a person giving a positive testimonial','Sense 1 is the singular legal meaning.','meaning'),Q(2,'“The accused are due to appear” refers to…','several charged people','one person with a permanent job','the people who edit a book','The plural verb are points to multiple defendants.','context'),Q(1,'Which sentence has plural agreement?','The accused are appearing together.','The accused is appearing together, referring to three people.','The accused am appearing together.','Are agrees with the collective plural group here.','grammar'),Q(1,'The word accused is formed from…','accuse plus the participial ending -ed','the article the plus -ology','thaw plus a plural ending','The phrase uses a participle as a noun for the charged person.','word-formation')]);
P('the author','The author combines the definite article with author, from Latin auctor, “originator or promoter”; in academic prose, “the author” can refer impersonally to the writer of the text.',C('the author.s1','文体指代','The author argues that the survey is incomplete and calls for more evidence.','作者认为这项调查并不完整，并呼吁提供更多证据。','the author argues/notes/concludes; the author of a text','名词短语，指文章、书或研究的撰写者，也常用于学术文体的客观自称。','the phrase identifies the writer whose argument appears in the text.','文体指代'),M('The author argues that the data are incomplete, although no writer produced or signed the text.','The author argues that the data are incomplete and supports that claim with evidence.','the author指文本的撰写者，原句否认存在任何作者。','meaning'),[Q(1,'In an article, “the author” usually means…','the person who wrote it','the person charged in a trial','the person who tests a machine','That is the phrase’s referent.','meaning'),Q(1,'What does the author argue in the example?','The survey is incomplete','The bridge is the tallest building','The accused should be acquitted','The sentence states the author’s position directly.','context'),Q(1,'Which phrase is natural in a paper?','The author argues that more evidence is needed.','The author argues that more evidence are needed.','The author argue more evidence that.','The singular subject author takes argues.','grammar'),Q(1,'Latin auctor referred to…','an originator or promoter','a small tile','a fear caused by violence','The word author descends from a Latin term for an originator.','word-formation')]);
P('the baby','The baby combines the definite article with baby; the definite form identifies a known child, and speakers sometimes use it affectionately for a cherished person or thing.',C('the baby.s1','亲昵称呼','The baby is asleep, so keep your voice down while we move the stroller.','宝宝睡着了，所以我们推婴儿车时轻一点。','the baby is sleeping; wake the baby','名词短语，指双方知道的婴儿，也可亲昵地称呼珍爱的人或物。','the phrase identifies the known child in the room.','亲昵称呼'),M('The baby is asleep, so we shouted beside the crib and woke the child at once.','The baby is asleep, so we spoke quietly and did not wake the child.','既然宝宝睡着了，大声喊叫会吵醒孩子，与句意相反。','meaning'),[Q(1,'In the example, the baby refers to…','the known infant in the stroller','a person on trial','a group of book editors','The article points to a particular child.','meaning'),Q(1,'Why should they lower their voices?','The baby is asleep','The child is taking a vocabulary test','The bus has reached its terminus','The context directly gives the reason.','context'),Q(1,'Which phrase is natural?','wake the baby','baby wake thely','wake to baby the','The baby is a normal noun phrase with the before the noun.','grammar'),Q(1,'The phrase is built from…','the definite article and the noun baby','thank plus -ness','a plural pronoun and a verb','The is used to identify a known child.','word-formation')]);
P('the disabled','The disabled combines the definite article with disabled used substantively to refer collectively to people with disabilities; many contexts prefer “disabled people” as a person-first group expression.',C('the disabled.s1','群体称谓','The new entrance was designed with a level ramp for the disabled.','新入口为残障人士设计了平缓坡道。','services/access for the disabled; support disabled people','名词短语，集体指有长期身体或精神障碍的人。','the ramp improves access for this group.','群体称谓'),M('The entrance was designed for the disabled, but it had only steep stairs and no accessible route.','The entrance was designed for the disabled, with a level ramp and wide doors.','为残障人士设计的入口应提供无障碍通行条件，陡楼梯会破坏这一目的。','meaning'),[Q(1,'In the source entry, the disabled refers to…','people with long-term disabilities as a group','people who edit books','all people who are temporarily tired','That is the collective noun phrase.','meaning'),Q(1,'What feature improves access?','A level ramp','A steep staircase only','A low ceiling at the doorway','The context says the entrance includes a ramp.','context'),Q(1,'Which alternative is often preferred in current prose?','disabled people','the disabled personses','the disable','The noun phrase disabled people is a clear people-focused alternative.','usage'),Q(1,'The phrase is formed by…','using the adjective disabled after the definite article as a group label','adding -ology to the noun disabled','using a past-tense verb before a plural noun','The article lets the adjective function as a collective noun phrase.','word-formation')]);
P('the editors','The editors combines the definite article with the plural of editor; it identifies the people who select, prepare, or revise the contents of a publication.',C('the editors.s1','出版','The editors welcome letters from readers on any topic related to the journal.','编辑们欢迎读者来信讨论与期刊有关的任何话题。','the editors of a journal; contact the editors','名词短语，指负责选择、整理或修改出版内容的编辑人员。','the phrase identifies the journal’s editorial team.','出版'),M('The editors welcomed letters, but the sentence says no person selected or prepared any publication content.','The editors welcomed letters and prepared the journal’s contents for publication.','editors的职责是选择和整理内容，原句否认有人履行这种职责。','meaning'),[Q(1,'The editors of a journal are…','people who prepare and select its contents','people charged with a crime','all readers of every newspaper','That matches the source meaning.','meaning'),Q(1,'What do the editors welcome?','Letters from readers','Requests to end a lease','Reports about a flock of terns','The sentence states that they welcome reader letters.','context'),Q(1,'Which sentence has natural agreement?','The editors welcome letters.','The editors welcomes letters.','The editors welcoming letters yesterday.','Plural editors takes the plural verb welcome.','grammar'),Q(1,'Editors is formed from…','edit plus the agent suffix -or and plural -s','thatch plus the ending -ness','the adjective young alone','The noun names people who edit and is plural here.','word-formation')]);
P('the first','The first uses the definite article with the ordinal first; it identifies the earliest person or thing in a series and can refer back to the earlier of two items.',[C('the first.s1','序列首位','The first of the guests arrived before noon and helped set the tables.','第一位客人在中午前到达，并帮忙摆好了桌子。','the first in line; the first of several','名词短语，指系列中排在最前的人或事物。','the guest arrives before the others.','序列首位'),C('the first.s2','两项中的前者','Of the two routes, the first is shorter but includes a steep hill.','两条路线中，第一条较短，但有一段陡坡。','the first of the two; the first option','名词短语，回指先前提到的两个人或事物中的前者。','the first refers to the route mentioned earlier.','两项中的前者')],M('Of the two routes, the first is shorter, but it refers to the second route just mentioned.','Of the two routes, the first is shorter, and it refers to the route mentioned first.','the first在两项比较中指较早提及的一项，不是后提及的第二项。','meaning'),[Q(1,'The first guest is…','the guest who arrives before the others','the last guest to leave','a person who writes the book','Sense 1 marks the earliest in a sequence.','meaning'),Q(2,'Of two routes, the first means…','the route mentioned earlier','a third route not mentioned','the route that is always longer','Sense 2 points to the first item in the pair.','context'),Q(1,'Which phrase is natural?','the first of the guests','first the of guests','the of first guests','The article precedes the ordinal phrase.','grammar'),Q(1,'First is an ordinal related to…','the number one and position at the beginning','fear and intimidation','a type of roof material','The ordinal identifies initial rank or order.','word-formation')]);
P('the future','The future combines the article with future, from Latin futurus, “about to be”; it refers to the time after the present.',C('the future.s1','未来','Nobody knows what the future will bring, so the team prepared several plans.','没人知道未来会发生什么，因此团队准备了几套方案。','in the near/distant future; plan for the future','名词短语，指当前时刻之后的时间。','the plans address events that have not happened yet.','未来'),M('The future will bring events that all happened before the present moment.','The future will bring events that have not happened yet.','future指现在之后的时间，不是已经发生的过去。','meaning'),[Q(1,'The future refers to…','time after the present','the time before birth only','the previous day','That is the source meaning.','meaning'),Q(1,'Why did the team prepare several plans?','It did not know what would happen','It knew every event in the future already','The journal editors asked for a word list','The example links planning with uncertainty about later events.','context'),Q(1,'Which phrase is natural?','in the near future','in futurely near','near of the future','Near modifies future in the common phrase.','collocation'),Q(1,'Latin futurus meant…','about to be','already ended','made of small tiles','The word’s origin points to what is yet to come.','word-formation')]);
P('the human race','The human race combines human with race, from Latin humanus and a word for a group or lineage; it refers to humanity collectively or to the species Homo sapiens.',[C('the human race.s1','全人类','The human race faces shared risks from climate change and new diseases.','人类共同面临气候变化和新疾病带来的风险。','the future of the human race; benefit the human race','名词短语，指全世界的人类作为一个整体。','the risks affect people across the world.','全人类'),C('the human race.s2','物种','Some fossils are older than the human race and belong to earlier hominin species.','有些化石比人类出现得更早，属于更早的人族物种。','members of the human race; evolution of the human race','名词短语，指包含所有现存人类的智人物种。','the comparison concerns when Homo sapiens appeared.','物种')],M('The human race includes every living person, but the sentence excludes all living people from humanity.','The human race includes every living person considered as one group.','the human race是全体人类的统称，不能同时排除所有人。','meaning'),[Q(1,'The human race in the climate sentence means…','all people considered together','one individual scientist','only the people in one town','Sense 1 is the collective meaning.','meaning'),Q(2,'Fossils older than the human race predate…','the appearance of Homo sapiens','the first public holiday','the beginning of a school term','Sense 2 concerns the species.','context'),Q(1,'Which phrase is natural?','the future of the human race','human race the future ofly','the human races future','Of links the future to the group whose future is meant.','grammar'),Q(1,'The phrase human race combines…','human with race, a group or lineage','text with book','th with an ordinal number','The compound names people as a single species or group.','word-formation')]);
P('the ill','The ill uses the definite article with ill as a substantivized adjective; it collectively refers to people who are suffering from illness.',C('the ill.s1','患病者','The clinic was set up to care for the ill in remote villages.','这家诊所是为照料偏远村庄里的病患而设立的。','care for/treat the ill; services for the ill','名词短语，集体指正在患病的人。','the clinic provides care to sick people.','患病者'),M('The clinic was created to care for the ill, but it refused to treat anyone who was sick.','The clinic was created to care for the ill and provide treatment to sick people.','the ill指患病者，拒绝治疗所有病人和诊所目的矛盾。','meaning'),[Q(1,'The ill refers collectively to…','people suffering from an illness','people who have no job','people who edit a journal','That is the substantivized adjective’s meaning.','meaning'),Q(1,'Why was the clinic established?','To care for sick people in remote villages','To publish a textbook','To test a bridge’s texture','The context states its purpose.','context'),Q(1,'Which verb agrees with the ill as a group?','The ill are receiving care.','The ill is receiving care, referring to all patients.','The ill am receiving care.','The plural group takes are in this construction.','grammar'),Q(1,'The phrase is formed by…','the plus an adjective used as a collective noun','a verb plus the suffix -ology','a noun and a past-tense ending','The article substantivizes ill to refer to a group.','word-formation')]);
P('the jobless','The jobless combines job with -less, “without,” used after the article as a collective adjective for people who do not have jobs and are seeking work.',C('the jobless.s1','失业者','The training scheme offers computer classes to the jobless in the region.','这项培训计划为本地区的失业者开设计算机课程。','support/help the jobless; the long-term jobless','名词短语，集体指没有工作并在寻找工作的人。','the course is aimed at unemployed jobseekers.','失业者'),M('The scheme supports the jobless, meaning people who all have stable full-time jobs.','The scheme supports the jobless, meaning people who lack work and are seeking employment.','the jobless指没有工作的人，和都有稳定全职工作相反。','meaning'),[Q(1,'The jobless are…','people without jobs who are looking for work','people who have permanent tenure','people who prepare a magazine','That is the collective meaning.','meaning'),Q(1,'What does the training scheme provide?','Computer classes','A legal testament','A sheltered tepee','The context says the scheme offers classes.','context'),Q(1,'Which sentence is natural?','The jobless are seeking work.','The jobless is seeking work, referring to all jobseekers.','The jobless seeks work are.','The collective plural group normally takes are.','grammar'),Q(1,'The suffix -less means…','without','full of','the act or process of','Jobless describes people without a job.','word-formation')]);
P('the like','The like combines the article with like in the sense “similar”; the phrase means people or things of the same kind as those just mentioned.',C('the like.s1','同类事物','He bought pens, paper, envelopes, and the like for the office.','他为办公室买了钢笔、纸、信封等类似物品。','and the like; people/things of the like','名词短语，指刚提到的同类人或事物。','the phrase extends the list to similar supplies.','同类事物'),M('She packed pens, paper, and the like, but by the phrase she meant unrelated items such as a bicycle and a fish.','She packed pens, paper, envelopes, and other office supplies of the like.','and the like指前面所列的同类物品，而非毫不相关的东西。','meaning'),[Q(1,'“Pens, paper, and the like” means…','pens, paper, and similar things','pens and paper followed by a new topic','a group of people on trial','The phrase extends a list with similar items.','meaning'),Q(1,'What did he buy?','Office supplies and similar items','A bus terminal and a terrace','Only unrelated household animals','The listed examples are office supplies.','context'),Q(1,'Which punctuation is common?','pens, paper, and the like','pens and the like paper','the like pens of paper','The phrase commonly follows a list after a comma.','grammar'),Q(1,'Like here means…','similar or of the same kind','frightening','the first in a series','The phrase uses like in its similarity sense.','word-formation')]);
P('the minority','The minority comes through French minorité from Latin minor, “smaller”; with the, it identifies the smaller part of a particular group.',C('the minority.s1','少数群体','The minority voted against the change, while most members supported it.','少数成员投票反对这项变更，而大多数人支持。','a small/the clear minority; minority of voters','名词短语，指某一群体中人数或比例较少的一方。','the group is smaller than the majority.','少数群体'),M('The minority was the largest part of the group, outnumbering every other member combined.','The minority was the smaller part of the group, while the majority outnumbered it.','minority指人数或比例较少的一方，不是占多数的一方。','meaning'),[Q(1,'The minority is…','the smaller part of a group','the whole group with no divisions','the previous day','That is the basic numerical meaning.','meaning'),Q(1,'How did the minority vote?','Against the change','Every member supported the change','They abstained because the meeting was cancelled','The context states that the smaller group voted against it.','context'),Q(1,'Which phrase is natural?','a minority of voters','a minority voters ofly','minority by voters a','Of introduces the larger set from which the smaller group comes.','grammar'),Q(1,'Latin minor meant…','smaller','future','writer','The word’s root expresses lesser size or number.','word-formation')]);
P('the next day','The next day combines the article with next and day; it means the day immediately following a day already mentioned or understood.',C('the next day.s1','次日','They signed the agreement on Friday and left for the coast the next day.','他们星期五签了协议，第二天便动身前往海岸。','the next day; on the next day','名词短语，指所谈事件之后紧接着的那一天。','the departure happens on Saturday after Friday.','次日'),M('They signed on Friday and left the next day, which means they left on Thursday.','They signed on Friday and left the next day, which means they left on Saturday.','the next day是星期五之后的一天，即星期六，不是星期四。','meaning'),[Q(1,'If they sign on Friday and leave the next day, they leave…','on Saturday','on Thursday','one month later','The next day immediately follows Friday.','context'),Q(1,'The next day refers to…','the day immediately after a referenced day','the day immediately before it','any day in the distant future','That is the phrase’s time relation.','meaning'),Q(1,'Which sentence is natural?','They arrived on the next day.','They arrived the next to day.','They arrived nextly day on.','The is followed by next day as a noun phrase.','grammar'),Q(1,'The phrase combines…','next with day to name a following date','the verb thank with -fulness','a court witness and a statement','Its meaning is compositional: the following day.','word-formation')]);
P('the past','The past comes from the participle of pass, ultimately from Latin passare, “to pass”; with the, it names time before now or someone’s earlier life and experiences.',[C('the past.s1','过去时间','The town has changed greatly in the past, especially since the bridge was built.','自从那座桥建成后，这座城镇在过去发生了很大变化。','in the recent/distant past; events of the past','名词短语，指现在之前已经发生的时间。','the changes occurred before the present.','过去时间'),C('the past.s2','个人经历','She rarely talks about her past before moving to the city.','她很少谈起搬到这座城市之前的人生经历。','a troubled/personal past; hide one’s past','名词短语，指一个人早先的经历或生活。','the phrase concerns her earlier life.','个人经历')],M('She rarely discusses her past before moving, meaning events that have not happened yet.','She rarely discusses her past before moving, meaning her earlier life and experiences.','the past指当前之前的经历，不是尚未发生的未来事件。','meaning'),[Q(1,'Changes in the past occurred…','before the present','after every possible future event','only in a person’s childhood','Sense 1 means earlier time.','meaning'),Q(2,'Her past before moving means…','her earlier life and experiences','the day immediately after moving','a legal contract’s conditions','Sense 2 is about personal history.','context'),Q(1,'Which phrase is natural?','in the distant past','on pastly distant','past of in distant','In the past is a standard time expression.','collocation'),Q(1,'Past is historically related to…','pass, meaning go by','texture, meaning surface feel','terror, meaning fear','The word names time that has passed.','word-formation')]);
P('the previous day','The previous day combines previous, from Latin praevius “going before,” with day; it means the day immediately before the day being discussed.',C('the previous day.s1','前一天','The guests arrived on Monday; the organizers had reached the hotel the previous day.','客人星期一到达；组织者前一天就已经抵达酒店。','on the previous day; during the previous day','名词短语，指相对于叙述时间紧邻在前的一天。','if guests arrive Monday, organizers came Sunday.','前一天'),M('The guests arrived Monday, and the organizers arrived the previous day, Tuesday.','The guests arrived Monday, and the organizers arrived the previous day, Sunday.','previous day指星期一之前的一天，应是星期日而不是星期二。','meaning'),[Q(1,'If guests arrive Monday, the previous day is…','Sunday','Tuesday','the following month','The previous day is the day before Monday.','context'),Q(1,'The previous day means…','the day immediately before the reference day','the day immediately after it','a distant period in the future','That is the phrase’s temporal meaning.','meaning'),Q(1,'Which phrase is correct?','on the previous day','on previous the day','the day previous on','The article precedes previous day.','grammar'),Q(1,'Previous comes from a Latin word meaning…','going before','being very warm','giving thanks','The etymology reflects the earlier-in-time sense.','word-formation')]);
P('the public','The public comes from Latin publicus, “of the people”; with the, it means ordinary people as a whole or a particular group using a service or following an activity.',[C('the public.s1','公众','The public has a right to know how the city spends its budget.','公众有权了解市政府如何使用预算。','inform/protect the public; in the public interest','名词短语，指社会中的普通人整体。','the budget affects citizens generally.','公众'),C('the public.s2','特定受众','The exhibition attracted a wider public than the museum’s usual visitors.','这场展览吸引了比博物馆常客更广泛的观众群体。','a reading/viewing public; reach a new public','名词短语，指某项服务、表演或出版物所面对的一类受众。','the exhibition reaches people beyond regular visitors.','特定受众')],M('The public has a right to know, meaning only one private official is entitled to the information.','The public has a right to know, meaning ordinary people are entitled to the information.','the public指公众群体，不是某一名私人官员。','meaning'),[Q(1,'The public in the budget example means…','ordinary people in society as a whole','only the city’s accounting team','the officials who wrote the budget','Sense 1 is the general-public meaning.','meaning'),Q(2,'A wider public for an exhibition means…','a broader group of viewers','a larger building with more windows','a more technical vocabulary','Sense 2 is an audience for an activity.','context'),Q(1,'Which phrase is natural?','inform the public','the public informly','inform to public the','Inform takes the public as its direct object.','grammar'),Q(1,'Latin publicus meant…','of the people','before the day','a small square tile','The root describes something belonging to people generally.','word-formation')]);
P('the rest','The rest comes from Old French reste, from Latin restare, “remain”; with the, it means all people or things left after some have been taken or mentioned.',C('the rest.s1','剩余部分','Some students stayed to clean the room; the rest went home.','一些学生留下来打扫房间，其余的人回家了。','the rest of the team; the rest of the food','名词短语，指一个群体中尚未提及或尚未处理的部分。','the phrase refers to everyone who did not stay.','剩余部分'),M('Some students stayed and the rest went home, meaning every student both stayed and left at once.','Some students stayed and the rest, the remaining students, went home.','the rest表示其余部分，与已留下的部分相区分。','meaning'),[Q(1,'The rest of the students are…','the students who remain after some are mentioned','the first students to arrive','students who teach the course','That is the phrase’s meaning.','meaning'),Q(1,'What did the rest do?','They went home','They stayed to clean','They held a testimonial dinner','The sentence contrasts them with those who stayed.','context'),Q(1,'Which phrase is natural?','the rest of the food','the food rest ofly','rest the of food','Of links the remaining part to its group.','grammar'),Q(1,'Latin restare meant…','to remain','to weave','to frighten','The word rest reflects what remains.','word-formation')]);
P('the universe','Universe comes from Latin universum, “the whole,” from unus “one” and versus “turned”; the universe means everything that exists in space, or figuratively one person’s world.',[C('the universe.s1','宇宙','The universe contains galaxies far beyond the stars visible from Earth.','宇宙中有许多远在地球肉眼可见恒星之外的星系。','the observable universe; study the universe','名词短语，指存在于空间中的所有物质与天体。','galaxies and stars are part of the whole cosmos.','宇宙'),C('the universe.s2','个人世界','After the studio opened, painting became the center of her universe.','工作室开办后，绘画成了她生活的中心。','the center of someone’s universe; one’s own universe','名词短语，指某个人所处的生活世界或关注范围。','painting dominates her personal life.','个人世界')],M('The universe contains only the Earth and nothing else in space.','The universe contains the Earth, stars, galaxies, and everything else in space.','宇宙指整个存在空间及其中事物，不只包括地球。','meaning'),[Q(1,'The universe in astronomy is…','everything that exists in space','one person’s favourite book only','a town’s public audience','Sense 1 is the cosmos.','meaning'),Q(2,'Painting became the center of her universe means…','it became central to her personal life','it became the center of every galaxy','she stopped living on Earth','Sense 2 is figurative.','context'),Q(1,'Which phrase is natural?','the observable universe','universe observablely the','an observe universe','Observable is an adjective modifying universe.','grammar'),Q(1,'Latin universum referred to…','the whole or all together','a small roof tile','a route’s last station','The origin reflects the idea of a unified whole.','word-formation')]);
P('the weekend','Weekend is a compound of week and end; the weekend is the part at the end of the week, commonly Saturday and Sunday when many people do not work.',C('the weekend.s1','周末','We are driving to the coast for the weekend and will return on Sunday evening.','我们要去海边过周末，星期日晚上回来。','at/on/over the weekend; weekend trip','名词短语，通常指星期六和星期日等一周末尾的休息时间。','the trip covers the customary days off.','周末'),M('They planned a weekend trip from Monday to Tuesday, the days at the start of the working week.','They planned a weekend trip for Saturday and Sunday.','weekend通常指一周末尾的休息日，不是星期初的工作日。','meaning'),[Q(1,'The weekend commonly includes…','Saturday and Sunday','Monday and Tuesday only','the previous and next day together','That is the usual meaning in the source entry.','meaning'),Q(1,'When will they return from the coast?','Sunday evening','Friday morning','The following month','The context gives the return time.','context'),Q(1,'Which phrase is natural?','over the weekend','at weekendly over','the weekend in over','Over the weekend describes a period spanning those days.','collocation'),Q(1,'Weekend combines…','week and end','thank and give','the and first','The compound names the end part of a week.','word-formation')]);
P('the young','The young uses the definite article with the adjective young as a collective noun; it refers to young people considered as a group.',C('the young.s1','年轻人','The young need safe places to study, play, and learn new skills.','年轻人需要安全的场所学习、玩耍并掌握新技能。','support/educate the young; opportunities for the young','名词短语，集体指年轻人。','the phrase covers young people generally.','年轻人'),M('The young need opportunities, meaning only people over eighty years old need them.','The young need opportunities, meaning young people need chances to learn and develop.','the young指年轻人，而不是八十岁以上的老年人。','meaning'),[Q(1,'The young means…','young people considered together','one particular newborn baby only','all the editors of a book','That is the collective adjective phrase.','meaning'),Q(1,'What do the young need in the example?','Safe chances to study, play, and learn','A legal will','A terminal for every airport','The sentence lists opportunities for young people.','context'),Q(1,'Which sentence is natural?','The young need support.','The young needs support, referring to all young people.','Young the need supports.','The collective plural phrase takes need.','grammar'),Q(1,'The phrase uses the adjective young…','as a collective noun for a group','as a verb meaning to become older','as a suffix meaning without','The article allows young to refer to people as a class.','word-formation')]);
P('theater','Theater comes through Latin and French from Greek theatron, “place for viewing,” from theasthai, “to watch”; it can mean a performance building, the art of drama, or a place where an activity occurs.',[C('theater.s1','剧院','We met outside the theater before the evening play began.','晚间话剧开演前，我们在剧院外碰面。','go to the theater; theater building','名词，指上演戏剧或电影的建筑。','the audience enters a venue for a performance.','剧院'),C('theater.s2','戏剧艺术','She has worked in theater for years, both as an actor and as a director.','她从事戏剧工作多年，既当演员也做导演。','work in theater; theater arts','名词，指戏剧创作与演出这一艺术活动。','her work spans acting and directing.','戏剧艺术'),C('theater.s3','手术室/活动场所','The patient was taken to the operating theater before dawn.','黎明前，病人被送进手术室。','operating theater; a theater of operations','名词，指手术室，或某类行动进行的区域。','the room is where surgeons operate.','手术室/活动场所')],M('They went to the theater to watch a play, but the building had no stage, screen, or performance space.','They went to the theater to watch a play in its performance space.','剧院是供演出或放映的场所，完全没有演出空间不符合语境。','meaning'),[Q(1,'Meeting outside the theater means meeting…','outside a building where plays or films are shown','inside a courtroom during testimony','at the end of a bus route','Sense 1 is the venue.','meaning'),Q(2,'Working in theater as an actor and director means…','working in the performing arts','working in a hospital only','working on a geological terrane','Sense 2 refers to drama as an art.','context'),Q(3,'An operating theater is…','a room where doctors perform surgery','a venue for political speeches only','an outdoor tiled terrace','Sense 3 is the medical room.','meaning'),Q(1,'Greek theatron meant…','a place for viewing','a boundary or limit','a feeling of gratitude','The Greek origin refers to watching a spectacle.','word-formation')]);
P('theatrical','Theatrical is formed from theater/theatre with -ical and ultimately from Greek theatron, “place for viewing”; it relates to acting and can describe exaggerated, showy behaviour.',[C('theatrical.s1','戏剧的','The school staged a theatrical production of a play by Shakespeare.','学校上演了一部莎士比亚戏剧作品。','theatrical performance/production; theatrical company','形容词，指与戏剧表演或剧院有关的。','the production is performed on stage.','戏剧的'),C('theatrical.s2','夸张做作','He gave a theatrical sigh so that everyone across the room would notice him.','他故意夸张地叹了口气，好让房间另一头的人都注意到他。','a theatrical gesture/sigh; behave theatrically','形容词，指举止像舞台表演一样夸张、引人注目的。','the sigh is performed for an audience.','夸张做作')],M('His theatrical sigh was quiet and completely unnoticed by everyone in the room.','His theatrical sigh was exaggerated so the whole room would notice.','theatrical在此表示夸张、做作且引人注意，与无人察觉相反。','meaning'),[Q(1,'A theatrical production is…','a stage performance','a school term','a public holiday','Sense 1 relates to theater and acting.','meaning'),Q(2,'A theatrical sigh is…','an exaggerated gesture meant to attract notice','a completely unobserved natural breath','a final legal statement','Sense 2 is figurative showiness.','context'),Q(1,'Which phrase is natural?','a theatrical performance','a theatrically performance','performance theatricalness','Theatrical is an adjective before the noun.','grammar'),Q(1,'Theatrical ultimately relates to Greek theatron, a…','place for viewing','woven textile','small square tile','The word’s origin refers to a place where people watch performances.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);
